INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (100, 'C01-0001', NULL, 'C01', 'safety_fire', 2, 'Apply', 'single', 'Smoke and a burning smell are coming from a 415 V distribution panel in a station electrical room. Nobody is hurt. You are the first person there. What should you do first?', 'स्थानकाच्या विद्युत कक्षातील 415 V वितरण पॅनेलमधून धूर व जळका वास येत आहे. कोणाला इजा नाही. तिथे पोहोचणारे तुम्ही पहिले आहात. तुम्ही प्रथम काय कराल?', 'Alarm and inform first so help and isolation start; fight the fire only if safe, and only with CO2 on electrical equipment. Opening the panel feeds the fire with air; any extinguisher may be water or foam; waiting loses time.', 'Alarm and inform first so help and isolation start; fight the fire only if safe, and only with CO2 on electrical equipment. Opening the panel feeds the fire with air; any extinguisher may be water or foam; waiting loses time.', 'आधी इशारा व माहिती दिल्याने मदत व विलगीकरण सुरू होते; सुरक्षित असल्यासच आग विझवा, आणि विद्युत उपकरणावर फक्त CO2 वापरा. पॅनेल उघडल्याने आगीला हवा मिळते; जवळचे अग्निशामक पाणी किंवा फोमचे असू शकते; थांबल्याने वेळ जातो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1000, 100, 1, 'Raise the alarm, inform the Station Controller, and use a CO2 extinguisher only if safe', 'इशारा द्या, स्टेशन कंट्रोलरला कळवा आणि सुरक्षित असल्यासच CO2 अग्निशामक वापरा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1001, 100, 2, 'Open the panel door to find the exact source, so that the report you give is accurate', 'अचूक माहिती देता यावी म्हणून पॅनेलचे दार उघडून नेमका स्रोत शोधा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1002, 100, 3, 'Switch off the incoming breaker yourself and spray the panel with the nearest extinguisher', 'स्वतः इनकमिंग ब्रेकर बंद करा आणि जवळच्या अग्निशामकाने पॅनेलवर फवारा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1003, 100, 4, 'Wait for the E&M maintainer, as only authorised staff may handle electrical panels', 'E&M देखभालकर्त्याची वाट पहा, कारण विद्युत पॅनेल फक्त अधिकृत कर्मचारीच हाताळू शकतात', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (101, 'C01-0002', NULL, 'C01', 'safety_fire', 2, 'Apply', 'sequence', 'A passenger collapses on the concourse and is not breathing normally. Put your first actions in the correct order.', 'कॉन्कोर्सवर एक प्रवासी कोसळतो आणि त्याचा श्वास सामान्य नाही. तुमच्या पहिल्या कृती योग्य क्रमाने लावा.', 'Basic life support order: safety, call for help and the AED, start CPR without delay, defibrillate as soon as the AED arrives.', 'Basic life support order: safety, call for help and the AED, start CPR without delay, defibrillate as soon as the AED arrives.', 'मूलभूत जीवनरक्षण क्रम: सुरक्षा, मदत व AED मागवणे, विलंब न करता CPR, AED येताच त्याचा वापर.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (102, 'C01-0003', NULL, 'C01', 'safety_fire', 3, 'Apply', 'multi', 'Which of these should be reported as a near-miss?', 'यापैकी कोणती घटना ''थोडक्यात टळलेली दुर्घटना'' (near-miss) म्हणून नोंदवावी?', 'A near-miss is an event or unsafe act that could have caused harm. Reporting them lets causes be removed before an accident.', 'A near-miss is an event or unsafe act that could have caused harm. Reporting them lets causes be removed before an accident.', 'ज्या घटनेमुळे किंवा असुरक्षित कृतीमुळे हानी होऊ शकली असती ती near-miss. ती नोंदवल्याने अपघातापूर्वीच कारणे दूर करता येतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1004, 102, 1, 'A luggage trolley rolls to the platform edge; a passenger stops it', 'सामानाची ट्रॉली प्लॅटफॉर्मच्या कडेकडे जाते; एक प्रवासी ती थांबवतो', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1005, 102, 2, 'A tool left on the track is found during the pre-service track check', 'सेवापूर्व रूळ-तपासणीत रुळावर राहिलेले साधन सापडते', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1006, 102, 3, 'A contractor''s worker is seen on the viaduct edge without a harness', 'कंत्राटदाराचा कामगार हार्नेसशिवाय व्हायाडक्टच्या कडेला दिसतो', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1007, 102, 4, 'A station fire drill finishes two minutes faster than its target time', 'स्थानकावरील अग्निशमन सराव लक्ष्य वेळेपेक्षा दोन मिनिटे आधी पूर्ण होतो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1008, 102, 5, 'A passenger says the platform air-conditioning is too cold', 'प्रवासी म्हणतो की प्लॅटफॉर्मवरील वातानुकूलन खूप थंड आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (103, 'C01-0004', NULL, 'C01', 'safety_fire', 2, 'Understand', 'truefalse', 'Stop-work authority belongs only to supervisors; a technician who sees an unsafe act should report it after the job is finished.', 'काम थांबवण्याचा अधिकार फक्त पर्यवेक्षकांना आहे; असुरक्षित कृती दिसल्यास तंत्रज्ञाने काम संपल्यानंतर ती कळवावी.', 'Every employee may stop work that is unsafe, at once, until it is made safe.', 'Every employee may stop work that is unsafe, at once, until it is made safe.', 'असुरक्षित काम कोणताही कर्मचारी ताबडतोब, ते सुरक्षित होईपर्यंत थांबवू शकतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1009, 103, 1, 'True', 'बरोबर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1010, 103, 2, 'False', 'चूक', 1, '');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (104, 'C01-0005', NULL, 'C01', 'safety_fire', 3, 'Analyse', 'sjt', 'You hear this alarm during peak hour. The fire panel shows one smoke detector in alarm on the concourse; nobody has reported smoke. What is the best first action?', 'गर्दीच्या वेळी हा इशारा ऐकू येतो. अग्नि-पॅनेलवर कॉन्कोर्समधील एक धूर-शोधक इशारा दाखवतो; धुराची कोणतीही माहिती आलेली नाही. सर्वोत्तम पहिली कृती कोणती?', 'A single-detector alarm is usually verified at once; confirmation or a second detector triggers evacuation. Resetting or calling it a test without checking is dangerous.', 'A single-detector alarm is usually verified at once; confirmation or a second detector triggers evacuation. Resetting or calling it a test without checking is dangerous.', 'एकाच शोधकाचा इशारा सहसा लगेच तपासला जातो; खात्री झाल्यास किंवा दुसरा शोधक सक्रिय झाल्यास स्थानक रिकामे केले जाते. न तपासता रीसेट करणे किंवा चाचणी म्हणणे धोकादायक आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1011, 104, 1, 'Send a staff member to check that detector at once and keep OCC informed', 'त्या शोधकाची तपासणी करण्यासाठी लगेच कर्मचारी पाठवा व OCC ला माहिती देत रहा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1012, 104, 2, 'Start a full station evacuation straight away and stop trains from stopping', 'लगेच संपूर्ण स्थानक रिकामे करा आणि गाड्यांचा थांबा बंद करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1013, 104, 3, 'Silence and reset the alarm from the panel to avoid causing passenger panic', 'प्रवाशांमध्ये घबराट होऊ नये म्हणून पॅनेलवरून इशारा बंद करून रीसेट करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1014, 104, 4, 'Announce on the PA that the alarm is a test and ask passengers to ignore it', 'PA वर इशारा चाचणी असल्याचे सांगा आणि प्रवाशांना दुर्लक्ष करण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (105, 'C01-0006', NULL, 'C01', 'safety_fire', 1, 'Remember', 'sequence', 'Arrange the steps for using a portable fire extinguisher.', 'पोर्टेबल अग्निशामक वापरण्याचे टप्पे क्रमाने लावा.', 'PASS: Pull, Aim, Squeeze, Sweep.', 'PASS: Pull, Aim, Squeeze, Sweep.', 'PASS: पिन काढा, नेम धरा, दाबा, फिरवा.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (106, 'C02-0001', NULL, 'C02', 'safety_fire', 2, 'Understand', 'single', 'On a CBTC line, what keeps two trains at a safe distance from each other?', 'CBTC मार्गावर दोन गाड्यांमध्ये सुरक्षित अंतर कशामुळे राखले जाते?', 'In CBTC the zone controller sends a movement authority and the onboard ATP enforces speed and braking within it.', 'In CBTC the zone controller sends a movement authority and the onboard ATP enforces speed and braking within it.', 'CBTC मध्ये झोन कंट्रोलर हालचाल-अधिकार पाठवतो आणि ऑनबोर्ड ATP त्या मर्यादेत वेग व ब्रेकिंग लागू करते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1015, 106, 1, 'Onboard ATP enforcing the movement authority it receives', 'मिळालेल्या हालचाल-अधिकाराची अंमलबजावणी करणारे ऑनबोर्ड ATP', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1016, 106, 2, 'The operator keeping a visual gap from the train ahead', 'पुढील गाडीपासून नजरेने अंतर राखणारा चालक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1017, 106, 3, 'Colour-light signals placed at fixed block sections', 'निश्चित ब्लॉक विभागांवरील रंगीत दिव्यांचे सिग्नल', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1018, 106, 4, 'OCC releasing each block section to trains by radio', 'प्रत्येक ब्लॉक विभाग रेडिओने गाड्यांना देणारे OCC', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (107, 'C02-0002', NULL, 'C02', 'safety_fire', 2, 'Apply', 'match', 'Match each fault with the department that should be called first.', 'प्रत्येक बिघाडासाठी आधी कोणत्या विभागाला बोलवावे ते जुळवा.', 'Call the department that owns the equipment first: escalators are E&M, gates are AFC, OHE breakers are Traction, and a false track occupancy is a signalling fault.', 'Call the department that owns the equipment first: escalators are E&M, gates are AFC, OHE breakers are Traction, and a false track occupancy is a signalling fault.', 'उपकरण ज्या विभागाचे आहे त्यालाच आधी कळवा: एस्केलेटर – E&M, गेट – AFC, OHE ब्रेकर – ट्रॅक्शन, आणि खोटी ट्रॅक व्याप्ती – सिग्नलिंग.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (108, 'C02-0003', NULL, 'C02', 'safety_fire', 2, 'Understand', 'single', 'A platform screen door does not close at the end of dwell. Which maintenance team is normally called?', 'थांब्याच्या शेवटी प्लॅटफॉर्म स्क्रीन दरवाजा बंद होत नाही. सामान्यतः कोणत्या देखभाल पथकाला बोलवले जाते?', 'At the CoE the PSD is housed in the Signalling Lab, reflecting its interlocking with train control.', 'At the CoE the PSD is housed in the Signalling Lab, reflecting its interlocking with train control.', 'CoE मध्ये PSD सिग्नलिंग लॅबमध्ये आहे, कारण तो ट्रेन-नियंत्रणाशी इंटरलॉक्ड आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1019, 108, 1, 'Signalling, as the PSD is interlocked with train control', 'सिग्नलिंग, कारण PSD ट्रेन-नियंत्रणाशी इंटरलॉक्ड असतो', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1020, 108, 2, 'E&M, as the doors are driven by electric motors', 'E&M, कारण दरवाजे विद्युत मोटरने चालतात', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1021, 108, 3, 'Rolling stock, as the train doors control the PSD', 'रोलिंग स्टॉक, कारण गाडीचे दरवाजे PSD नियंत्रित करतात', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1022, 108, 4, 'Civil, as the PSD is fixed to the platform edge', 'स्थापत्य, कारण PSD प्लॅटफॉर्मच्या कडेला बसवलेला असतो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (109, 'C02-0004', NULL, 'C02', 'safety_fire', 2, 'Understand', 'multi', 'Which of these must be reported to OCC at once?', 'यापैकी कोणती बाब OCC ला ताबडतोब कळवली पाहिजे?', 'Anything that affects train or passenger safety goes to OCC at once. Paper rolls and late housekeeping staff are handled locally.', 'Anything that affects train or passenger safety goes to OCC at once. Paper rolls and late housekeeping staff are handled locally.', 'गाडी किंवा प्रवाशांच्या सुरक्षेवर परिणाम करणारी प्रत्येक गोष्ट OCC ला लगेच कळवा. पावती-रोल किंवा उशिरा आलेले कर्मचारी स्थानिक पातळीवर हाताळले जातात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1023, 109, 1, 'A person seen walking on the viaduct track', 'व्हायाडक्टवरील रुळावरून चालणारी व्यक्ती दिसणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1024, 109, 2, 'A platform screen door that will not close', 'बंद न होणारा प्लॅटफॉर्म स्क्रीन दरवाजा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1025, 109, 3, 'A passenger injured in a fall on an escalator', 'एस्केलेटरवर पडून जखमी झालेला प्रवासी', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1026, 109, 4, 'A ticket vending machine out of receipt paper', 'पावतीचा कागद संपलेले तिकीट यंत्र', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1027, 109, 5, 'A housekeeping contractor arriving 20 minutes late', 'स्वच्छता कंत्राटदार 20 मिनिटे उशिरा येणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (110, 'C02-0005', NULL, 'C02', 'safety_fire', 1, 'Remember', 'truefalse', 'Trains on Maha Metro''s Nagpur and Pune lines draw traction power from a 25 kV AC overhead line.', 'महा मेट्रोच्या नागपूर व पुणे मार्गांवरील गाड्या 25 kV AC ओव्हरहेड लाइनमधून ट्रॅक्शन वीज घेतात.', 'Both the Nagpur and Pune metro lines use 25 kV AC overhead equipment (OHE) for traction, not a third rail.', 'Both the Nagpur and Pune metro lines use 25 kV AC overhead equipment (OHE) for traction, not a third rail.', 'नागपूर व पुणे या दोन्ही मेट्रो मार्गांवर ट्रॅक्शनसाठी 25 kV AC ओव्हरहेड उपकरण (OHE) वापरले जाते, तिसरी रेल्वे नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1028, 110, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1029, 110, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (111, 'C03-0001', NULL, 'C03', 'safety_fire', 3, 'Apply', 'sjt', 'A wheelchair user wants to reach the platform, but the only lift on that side is out of service. What is the best response?', 'व्हीलचेअर वापरकर्त्याला प्लॅटफॉर्मवर जायचे आहे, पण त्या बाजूची एकमेव लिफ्ट बंद आहे. सर्वोत्तम प्रतिसाद कोणता?', 'Escorting keeps the passenger safe and informing the destination ensures help on arrival. Wheelchairs on escalators are unsafe even with help.', 'Escorting keeps the passenger safe and informing the destination ensures help on arrival. Wheelchairs on escalators are unsafe even with help.', 'सोबत नेल्याने प्रवासी सुरक्षित राहतो व गंतव्य स्थानकाला कळवल्याने पोहोचल्यावर मदत मिळते. मदत असली तरी एस्केलेटरवर व्हीलचेअर असुरक्षित आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1030, 111, 1, 'Escort the passenger to the working lift on the other side and inform the destination', 'प्रवाशाला दुसऱ्या बाजूच्या चालू लिफ्टपर्यंत घेऊन जा व गंतव्य स्थानकाला कळवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1031, 111, 2, 'Explain clearly where the working lift is and how to reach it from the concourse', 'चालू लिफ्ट कोठे आहे व कॉन्कोर्समधून तिथे कसे जायचे ते स्पष्ट सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1032, 111, 3, 'Arrange two staff members to help the passenger up the escalator carefully', 'दोन कर्मचाऱ्यांच्या मदतीने प्रवाशाला काळजीपूर्वक एस्केलेटरने वर न्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1033, 111, 4, 'Suggest boarding at the next station, where lifts work, and call that station', 'लिफ्ट चालू असलेल्या पुढील स्थानकातून प्रवास सुचवा व त्या स्थानकाला कळवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (112, 'C03-0002', NULL, 'C03', 'safety_fire', 3, 'Apply', 'sjt', 'A passenger says the gate deducted the fare twice from his card and is getting angry. What do you do?', 'एक प्रवासी म्हणतो की गेटने त्याच्या कार्डमधून दोनदा भाडे कापले आणि तो संतप्त होत आहे. तुम्ही काय कराल?', 'Checking the transaction record resolves the complaint on the spot and within the rules; an unrecorded cash refund breaks revenue controls.', 'Checking the transaction record resolves the complaint on the spot and within the rules; an unrecorded cash refund breaks revenue controls.', 'व्यवहाराची नोंद तपासल्याने तक्रार जागीच व नियमांनुसार सुटते; नोंद न करता रोख परतावा दिल्यास महसूल नियंत्रण मोडते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1034, 112, 1, 'Check the card history at the ticket office and correct or refund it as per rules', 'तिकीट कार्यालयात कार्डचा इतिहास तपासा व नियमांनुसार दुरुस्ती किंवा परतावा करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1035, 112, 2, 'Give him the complaint number and ask him to follow up with customer care', 'त्याला तक्रार क्रमांक द्या व ग्राहक सेवेकडे पाठपुरावा करण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1036, 112, 3, 'Refund the fare in cash from the counter at once to calm the situation', 'परिस्थिती शांत करण्यासाठी काउंटरवरून लगेच रोख भाडे परत द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1037, 112, 4, 'Explain that gates rarely make errors and suggest he contact his bank', 'गेट क्वचितच चूक करतात असे समजावून बँकेशी संपर्क करण्यास सुचवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (113, 'C03-0003', NULL, 'C03', 'safety_fire', 2, 'Apply', 'single', 'You are counting cash at the ticket office when a passenger starts complaining loudly about a 15-minute delay. What should you do first?', 'तिकीट कार्यालयात तुम्ही रोख मोजत असताना एक प्रवासी 15 मिनिटांच्या विलंबाबद्दल मोठ्याने तक्रार करू लागतो. तुम्ही प्रथम काय कराल?', 'Cash must never be left exposed, but the passenger must not be ignored either. Secure the cash in seconds, then listen fully.', 'Cash must never be left exposed, but the passenger must not be ignored either. Secure the cash in seconds, then listen fully.', 'रोकड उघडी ठेवू नये, पण प्रवाशाकडे दुर्लक्षही करू नये. काही सेकंदांत रोकड सुरक्षित करा व मग पूर्ण लक्ष द्या.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1038, 113, 1, 'Secure the cash, then give the passenger your full attention', 'रोख सुरक्षित ठेवा, मग प्रवाशाकडे पूर्ण लक्ष द्या', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1039, 113, 2, 'Finish counting first so that no cash error is made', 'रोख चूक होऊ नये म्हणून आधी मोजणी पूर्ण करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1040, 113, 3, 'Explain that train delays are handled by OCC, not stations', 'गाड्यांचा विलंब OCC हाताळते, स्थानक नाही असे सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1041, 113, 4, 'Hand over a complaint form and continue with your work', 'तक्रार अर्ज देऊन तुमचे काम सुरू ठेवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (114, 'C03-0004', NULL, 'C03', 'safety_fire', 2, 'Apply', 'sjt', 'A visually impaired passenger asks for help to reach platform 2 during peak hour. What is the best response?', 'गर्दीच्या वेळी एक दृष्टिहीन प्रवासी प्लॅटफॉर्म 2 वर जाण्यासाठी मदत मागतो. सर्वोत्तम प्रतिसाद कोणता?', 'Personal guidance with a handover to platform staff is safest and most respectful. Directions alone help less in a peak crowd; leaving him with a stranger or making him wait is poor service.', 'Personal guidance with a handover to platform staff is safest and most respectful. Directions alone help less in a peak crowd; leaving him with a stranger or making him wait is poor service.', 'स्वतः मार्गदर्शन करून प्लॅटफॉर्म कर्मचाऱ्यांकडे सोपवणे सर्वात सुरक्षित व आदरपूर्ण आहे. गर्दीत फक्त मार्ग सांगणे कमी उपयोगी; अनोळखी व्यक्तीबरोबर पाठवणे किंवा थांबायला लावणे ही वाईट सेवा आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1042, 114, 1, 'Offer your arm, guide him to the platform and tell the platform staff', 'तुमचा हात देऊ करा, त्याला प्लॅटफॉर्मपर्यंत न्या व प्लॅटफॉर्म कर्मचाऱ्यांना सांगा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1043, 114, 2, 'Describe the route along the tactile path and the lift to use', 'स्पर्श-मार्ग व वापरायची लिफ्ट यांचे मार्गवर्णन सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1044, 114, 3, 'Ask a passenger going the same way to take him along', 'त्याच दिशेने जाणाऱ्या प्रवाशाला त्याला सोबत नेण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1045, 114, 4, 'Ask him to wait near the SCR until the peak crowd clears', 'गर्दी कमी होईपर्यंत SCR जवळ थांबण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (115, 'C04-0001', NULL, 'C04', 'safety_fire', 2, 'Apply', 'sjt', 'A contractor''s representative leaves an expensive gift at your desk after a bill you processed was cleared. What is the best response?', 'तुम्ही प्रक्रिया केलेले बिल मंजूर झाल्यानंतर कंत्राटदाराचा प्रतिनिधी तुमच्या टेबलवर महागडी भेटवस्तू ठेवून जातो. सर्वोत्तम प्रतिसाद कोणता?', 'Gifts from parties with official dealings must be declined or reported; a cleared bill does not remove the expectation of future favour.', 'Gifts from parties with official dealings must be declined or reported; a cleared bill does not remove the expectation of future favour.', 'अधिकृत व्यवहार असलेल्यांकडील भेटवस्तू नाकाराव्या किंवा कळवाव्या; बिल मंजूर झाले तरी भविष्यातील उपकाराची अपेक्षा संपत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1046, 115, 1, 'Return it and report it as required by the conduct rules', 'आचार नियमांनुसार ती परत करा व त्याची माहिती द्या', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1047, 115, 2, 'Keep it and declare it in your next annual property return', 'ती ठेवा व पुढील वार्षिक मालमत्ता विवरणात जाहीर करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1048, 115, 3, 'Hand it to the department for common use and thank him', 'सामायिक वापरासाठी विभागाकडे द्या व त्याचे आभार माना', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1049, 115, 4, 'Accept it, as the bill is already cleared and cannot be influenced', 'बिल आधीच मंजूर झाल्याने प्रभाव पडत नाही, म्हणून स्वीकारा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (116, 'C04-0002', NULL, 'C04', 'safety_fire', 3, 'Apply', 'single', 'You are on a bid evaluation committee and learn that your brother-in-law''s firm has bid. What should you do?', 'तुम्ही निविदा मूल्यमापन समितीवर आहात आणि तुमच्या मेहुण्याच्या फर्मने निविदा भरली आहे हे कळते. काय करावे?', 'A conflict of interest must be declared in writing and the officer must withdraw from the whole evaluation. Not scoring one bid or an oral mention is not enough.', 'A conflict of interest must be declared in writing and the officer must withdraw from the whole evaluation. Not scoring one bid or an oral mention is not enough.', 'हितसंबंधांचा संघर्ष लेखी जाहीर करून संपूर्ण मूल्यमापनातून बाजूला व्हावे. फक्त एक बोली न तपासणे किंवा तोंडी सांगणे पुरेसे नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1050, 116, 1, 'Declare the relationship in writing and step aside from the evaluation', 'नाते लेखी जाहीर करा व मूल्यमापनातून बाजूला व्हा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1051, 116, 2, 'Continue, but do not score that particular firm''s bid yourself', 'सुरू ठेवा, पण त्या फर्मच्या निविदेला स्वतः गुण देऊ नका', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1052, 116, 3, 'Tell the committee chair orally and continue as a member', 'समिती अध्यक्षांना तोंडी सांगा व सदस्य म्हणून सुरू ठेवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1053, 116, 4, 'Ask your relative''s firm to withdraw so the conflict ends', 'संघर्ष संपावा म्हणून नातेवाईकाच्या फर्मला माघार घेण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (117, 'C04-0003', NULL, 'C04', 'safety_fire', 2, 'Understand', 'truefalse', 'Preventive vigilance is the responsibility of the vigilance department only.', 'प्रतिबंधात्मक दक्षता ही केवळ दक्षता विभागाची जबाबदारी आहे.', 'Every employee and manager is responsible for preventive vigilance in their own work.', 'Every employee and manager is responsible for preventive vigilance in their own work.', 'प्रत्येक कर्मचारी व व्यवस्थापक आपल्या कामात प्रतिबंधात्मक दक्षतेसाठी जबाबदार आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1054, 117, 1, 'True', 'बरोबर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1055, 117, 2, 'False', 'चूक', 1, '');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (118, 'C04-0004', NULL, 'C04', 'safety_fire', 3, 'Analyse', 'single', 'While checking a contractor''s bill, you find the claimed quantity is 8% more than what you measured at site. The engineer-in-charge says, ''Pass it; we will adjust it in the next bill.'' What do you do?', 'कंत्राटदाराचे बिल तपासताना दावा केलेले प्रमाण तुम्ही साइटवर मोजलेल्यापेक्षा 8% जास्त आढळते. प्रभारी अभियंता म्हणतात, ''मंजूर करा; पुढील बिलात समायोजित करू.'' तुम्ही काय कराल?', 'Bills are paid only for work measured. Record the true quantity and put the difference on file. ''Adjusting later'' is overpayment and a vigilance risk.', 'Bills are paid only for work measured. Record the true quantity and put the difference on file. ''Adjusting later'' is overpayment and a vigilance risk.', 'मोजलेल्या कामासाठीच बिल दिले जाते. खरे परिमाण नोंदवा व फरक फाइलवर मांडा. ''नंतर समायोजन'' म्हणजे जादा देयक व दक्षता धोका.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1056, 118, 1, 'Record the measured quantity and put up a note on the difference', 'मोजलेले प्रमाण नोंदवा व फरकाबाबत टिप्पणी सादर करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1057, 118, 2, 'Pass it as told, since the excess will be recovered later', 'सांगितल्याप्रमाणे मंजूर करा, कारण जादा रक्कम नंतर वसूल होईल', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1058, 118, 3, 'Pass it, but keep a personal record in case of an audit', 'मंजूर करा, पण लेखापरीक्षेसाठी वैयक्तिक नोंद ठेवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1059, 118, 4, 'Return the bill to the contractor without any comment', 'कोणतीही टिप्पणी न करता बिल कंत्राटदाराला परत करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (119, 'C04-0005', NULL, 'C04', 'safety_fire', 1, 'Remember', 'single', 'Vigilance Awareness Week is observed every year in the week that includes which date?', 'दक्षता जागरूकता सप्ताह दरवर्षी कोणत्या तारखेचा समावेश असलेल्या आठवड्यात पाळला जातो?', 'It is observed in the week of Sardar Vallabhbhai Patel''s birth anniversary, 31 October.', 'It is observed in the week of Sardar Vallabhbhai Patel''s birth anniversary, 31 October.', 'हा सरदार वल्लभभाई पटेल यांच्या जयंतीच्या (31 ऑक्टोबर) आठवड्यात पाळला जातो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1060, 119, 1, '31 October', '31 ऑक्टोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1061, 119, 2, '15 August', '15 ऑगस्ट', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1062, 119, 3, '2 October', '2 ऑक्टोबर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1063, 119, 4, '26 November', '26 नोव्हेंबर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (120, 'C05-0001', NULL, 'C05', 'safety_fire', 2, 'Apply', 'single', 'An email that looks like it is from IT asks you to confirm your ERP password through a link ''before your account is locked today''. What should you do?', 'IT कडून आल्यासारखा ई-मेल ''आज खाते लॉक होण्यापूर्वी'' लिंकद्वारे ERP पासवर्ड पुष्टी करण्यास सांगतो. तुम्ही काय कराल?', 'Urgency plus a password request is a classic phishing sign. Contact details inside the email belong to the attacker too.', 'Urgency plus a password request is a classic phishing sign. Contact details inside the email belong to the attacker too.', 'घाई व पासवर्डची मागणी हे फिशिंगचे ठळक लक्षण आहे. ई-मेलमधील संपर्क तपशीलही हल्लेखोराचेच असतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1064, 120, 1, 'Do not click; report it to IT as suspected phishing', 'क्लिक करू नका; संशयित फिशिंग म्हणून IT ला कळवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1065, 120, 2, 'Open the link on your mobile, not on the office PC', 'लिंक कार्यालयीन संगणकाऐवजी मोबाईलवर उघडा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1066, 120, 3, 'Call the phone number in the email to check it first', 'आधी ई-मेलमधील फोन क्रमांकावर फोन करून खात्री करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1067, 120, 4, 'Reply asking the sender to confirm their identity', 'उत्तर पाठवून पाठवणाऱ्याची ओळख निश्चित करण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (121, 'C05-0002', NULL, 'C05', 'safety_fire', 2, 'Understand', 'multi', 'Which of these are good password practices?', 'यापैकी पासवर्डच्या चांगल्या पद्धती कोणत्या?', 'Length, multi-factor authentication and unique passwords protect accounts. Small monthly changes are easy to guess, and a note file on the desktop can be read by anyone.', 'Length, multi-factor authentication and unique passwords protect accounts. Small monthly changes are easy to guess, and a note file on the desktop can be read by anyone.', 'लांबी, बहु-घटक प्रमाणीकरण व प्रत्येक प्रणालीसाठी वेगळा पासवर्ड खाते सुरक्षित ठेवतात. दरमहा एक अंक बदलणे सहज ओळखता येते, आणि डेस्कटॉपवरील नोट कोणीही वाचू शकतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1068, 121, 1, 'Use a long passphrase of 12 or more characters', '12 किंवा अधिक अक्षरांचा लांब पासफ्रेज वापरा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1069, 121, 2, 'Turn on multi-factor authentication where offered', 'उपलब्ध असेल तिथे बहु-घटक प्रमाणीकरण सुरू करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1070, 121, 3, 'Use a different password for each system', 'प्रत्येक प्रणालीसाठी वेगळा पासवर्ड वापरा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1071, 121, 4, 'Change one digit each month to keep it memorable', 'लक्षात राहावा म्हणून दर महिन्याला एक अंक बदला', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1072, 121, 5, 'Save it in a note file on the office desktop', 'कार्यालयीन डेस्कटॉपवरील नोट फाइलमध्ये साठवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (122, 'C05-0003', NULL, 'C05', 'safety_fire', 2, 'Apply', 'sjt', 'A colleague asks for your ERP login so he can finish urgent entries while you are on leave next week. What is the best response?', 'पुढील आठवड्यात तुम्ही रजेवर असताना तातडीच्या नोंदी पूर्ण करण्यासाठी सहकारी तुमचा ERP लॉगिन मागतो. सर्वोत्तम प्रतिसाद कोणता?', 'Logins are personal and every entry is traced to the owner. The right route is temporary access issued by IT. Sharing credentials breaks policy even for official work.', 'Logins are personal and every entry is traced to the owner. The right route is temporary access issued by IT. Sharing credentials breaks policy even for official work.', 'लॉगिन वैयक्तिक असतो व प्रत्येक नोंद त्याच्या मालकाच्या नावावर जाते. योग्य मार्ग म्हणजे IT कडून तात्पुरता प्रवेश. अधिकृत कामासाठीही पासवर्ड देणे नियमभंग आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1073, 122, 1, 'Decline, and ask the supervisor to get him temporary access through IT', 'नकार द्या व पर्यवेक्षकांना IT मार्फत त्याला तात्पुरता प्रवेश मिळवून देण्यास सांगा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1074, 122, 2, 'Log in remotely from home yourself and do the entries for him', 'घरून स्वतः दूरस्थपणे लॉगिन करून त्याच्यासाठी नोंदी करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1075, 122, 3, 'Share it, and change the password as soon as you return', 'शेअर करा व परत आल्यावर लगेच पासवर्ड बदला', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1076, 122, 4, 'Share it, because the entries are for official work only', 'शेअर करा, कारण नोंदी फक्त अधिकृत कामासाठीच आहेत', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (123, 'C05-0004', NULL, 'C05', 'safety_fire', 2, 'Apply', 'single', 'You find a USB pen drive labelled ''Salary revision 2027'' in the car park. What should you do?', 'पार्किंगमध्ये ''वेतन सुधारणा 2027'' असे लेबल असलेला USB पेन ड्राइव्ह सापडतो. तुम्ही काय कराल?', 'Tempting labels are a known trick to plant malware; only IT should examine unknown devices.', 'Tempting labels are a known trick to plant malware; only IT should examine unknown devices.', 'आकर्षक लेबल लावून मालवेअर पसरवणे ही ज्ञात युक्ती आहे; अनोळखी उपकरण फक्त IT नेच तपासावे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1077, 123, 1, 'Hand it to IT without plugging it into any computer', 'कोणत्याही संगणकाला न लावता IT कडे जमा करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1078, 123, 2, 'Plug it into an office PC that has antivirus to find the owner', 'मालक शोधण्यासाठी अँटीव्हायरस असलेल्या कार्यालयीन संगणकाला लावा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1079, 123, 3, 'Give it to HR, since it seems to contain salary data', 'वेतन माहिती असल्यासारखे दिसते म्हणून HR कडे द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1080, 123, 4, 'Check it on a home laptop so office systems stay safe', 'कार्यालयीन प्रणाली सुरक्षित राहाव्यात म्हणून घरच्या लॅपटॉपवर तपासा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (124, 'C06-0001', NULL, 'C06', 'safety_fire', 2, 'Apply', 'single', 'OCC tells you by radio: ''Train 112, proceed at caution to platform 2 and stop short of the obstruction.'' What is the correct reply?', 'OCC रेडिओवर सांगते: ''ट्रेन 112, सावधगिरीने प्लॅटफॉर्म 2 कडे जा आणि अडथळ्याच्या अलीकडे थांबा.'' योग्य उत्तर कोणते?', 'Repeat-back of safety-critical instructions confirms the exact message before acting.', 'Repeat-back of safety-critical instructions confirms the exact message before acting.', 'सुरक्षा-महत्त्वाच्या सूचना पुन्हा उच्चारल्याने कृतीपूर्वी नेमका संदेश निश्चित होतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1081, 124, 1, 'Repeat the instruction back in full and wait for ''correct''', 'संपूर्ण सूचना पुन्हा उच्चारा आणि ''बरोबर'' ची वाट पहा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1082, 124, 2, 'Say ''Roger, OCC'' and start moving at caution speed', '''रॉजर, OCC'' म्हणा आणि सावध वेगाने निघा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1083, 124, 3, 'Give your train number, acknowledge, and act on the instruction', 'तुमचा ट्रेन क्रमांक सांगा, पोच द्या आणि सूचनेनुसार कृती करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1084, 124, 4, 'Ask OCC to send the same instruction as a message', 'हीच सूचना संदेशाद्वारे पाठवण्यास OCC ला सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (125, 'C06-0002', NULL, 'C06', 'safety_fire', 3, 'Apply', 'audio_response', 'Record a public announcement (in the language you selected) telling passengers that the next train is delayed by about 10 minutes due to a technical problem.', 'तांत्रिक अडचणीमुळे पुढील गाडी सुमारे 10 मिनिटे उशिरा असल्याची प्रवाशांना माहिती देणारी उद्घोषणा (निवडलेल्या भाषेत) रेकॉर्ड करा.', 'Review operational protocols and standard safety manuals.', 'Operational correctness derived from G&SR.', 'जी आणि एसआर नियमांनुसार अचूक कार्यपद्धती.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (126, 'C06-0003', NULL, 'C06', 'safety_fire', 3, 'Apply', 'short_text', 'Write a short incident note (5–8 lines) to your superior about a passenger who slipped on a wet floor near the station entry. The passenger was not seriously hurt.', 'स्थानक प्रवेशाजवळ ओल्या फरशीवर घसरलेल्या प्रवाशाबद्दल वरिष्ठांना छोटी घटना-नोंद (5–8 ओळी) लिहा. प्रवाशाला गंभीर इजा झाली नाही.', 'Review operational protocols and standard safety manuals.', 'Operational correctness derived from G&SR.', 'जी आणि एसआर नियमांनुसार अचूक कार्यपद्धती.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (127, 'C06-0004', NULL, 'C06', 'safety_fire', 2, 'Apply', 'single', 'Trains are delayed by about 10 minutes. Which platform announcement is best?', 'गाड्यांना सुमारे 10 मिनिटांचा विलंब आहे. प्लॅटफॉर्मवरील कोणती उद्घोषणा सर्वोत्तम?', 'A good announcement gives a simple reason, the expected wait and an apology; ''until further notice'' and ''contact the desk'' leave passengers without the information they need.', 'A good announcement gives a simple reason, the expected wait and an apology; ''until further notice'' and ''contact the desk'' leave passengers without the information they need.', 'चांगल्या उद्घोषणेत सोपे कारण, अपेक्षित प्रतीक्षा व दिलगिरी असते; ''पुढील सूचनेपर्यंत'' किंवा ''कक्षाशी संपर्क'' यामुळे प्रवाशांना आवश्यक माहिती मिळत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1085, 127, 1, '''Due to a technical problem, the next train will arrive in about 10 minutes. We regret the delay.''', '''तांत्रिक अडचणीमुळे पुढील गाडी सुमारे 10 मिनिटांत येईल. विलंबाबद्दल आम्ही दिलगीर आहोत.''', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1086, 127, 2, '''Trains are running late. Please wait on the platform and do not crowd near the edge.''', '''गाड्या उशिराने धावत आहेत. कृपया प्लॅटफॉर्मवर थांबा व कडेजवळ गर्दी करू नका.''', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1087, 127, 3, '''Due to a signalling failure between stations, services are disrupted until further notice.''', '''स्थानकांदरम्यान सिग्नलिंग बिघाडामुळे पुढील सूचनेपर्यंत सेवा विस्कळीत आहे.''', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1088, 127, 4, '''The next train is delayed. For details, please contact the customer care desk.''', '''पुढील गाडी उशिरा आहे. तपशिलासाठी कृपया ग्राहक सेवा कक्षाशी संपर्क साधा.''', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (128, 'B01-0001', NULL, 'B01', 'workplace_ethics', 3, 'Apply', 'sjt', 'The night maintenance block is ending. Another department''s team is still clearing material from the track; your team has finished. What do you do?', 'रात्रीचा देखभाल ब्लॉक संपत आला आहे. दुसऱ्या विभागाची टीम अजून रुळावरील साहित्य हटवत आहे; तुमचे काम पूर्ण झाले आहे. तुम्ही काय कराल?', 'The block is shared, so offering help and keeping the controller informed returns the line sooner. Only reporting is partial; leaving ignores the shared goal.', 'The block is shared, so offering help and keeping the controller informed returns the line sooner. Only reporting is partial; leaving ignores the shared goal.', 'ब्लॉक सर्वांचा असतो; मदत देऊन नियंत्रकाला माहिती दिल्यास मार्ग लवकर मोकळा होतो. फक्त कळवणे अपुरे; निघून जाणे सामायिक उद्दिष्टाकडे दुर्लक्ष आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1089, 128, 1, 'Offer your team''s help, agree it with their in-charge and update the controller', 'तुमच्या टीमची मदत देऊ करा, त्यांच्या प्रभारीशी ठरवा व नियंत्रकाला माहिती द्या', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1090, 128, 2, 'Tell the controller your part is clear and that the other team is still working', 'तुमचा भाग मोकळा असून दुसरी टीम काम करत आहे असे नियंत्रकाला सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1091, 128, 3, 'Sign off your part of the block and leave, as their work is their responsibility', 'तुमच्या भागाचा ब्लॉक बंद करून निघा, कारण त्यांचे काम त्यांची जबाबदारी आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1092, 128, 4, 'Wait on site without interfering until they finish, then leave together', 'हस्तक्षेप न करता ते पूर्ण करेपर्यंत थांबा, मग एकत्र निघा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (129, 'B01-0002', NULL, 'B01', 'workplace_ethics', 2, 'Apply', 'sjt', 'A colleague on another shift regularly leaves handover notes incomplete. What is the best approach?', 'दुसऱ्या पाळीतील सहकारी नियमितपणे हस्तांतरण नोंदी अपूर्ण ठेवतो. सर्वोत्तम पद्धत कोणती?', 'Raise it directly first and agree a fix (a checklist). Escalate only if it continues. Quietly covering for him or copying the bad practice keeps the risk.', 'Raise it directly first and agree a fix (a checklist). Escalate only if it continues. Quietly covering for him or copying the bad practice keeps the risk.', 'आधी थेट बोलून उपाय (चेकलिस्ट) ठरवा; तरीही चालू राहिल्यास वरिष्ठांकडे न्या. गुपचूप भरपाई करणे किंवा तशीच सवय लावणे धोका कायम ठेवते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1093, 129, 1, 'Talk to him, agree a handover checklist, and escalate if it continues', 'त्याच्याशी बोला, हस्तांतरण-यादी ठरवा व तरीही सुरू राहिल्यास वरिष्ठांकडे न्या', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1094, 129, 2, 'Fill in the missing details yourself each time so that work is not affected', 'काम अडू नये म्हणून प्रत्येक वेळी गहाळ तपशील स्वतः भरा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1095, 129, 3, 'Report the incomplete notes to the supervisor in writing straight away', 'अपूर्ण नोंदींची लेखी तक्रार लगेच पर्यवेक्षकाकडे करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1096, 129, 4, 'Leave your own handover notes equally brief so the shifts stay consistent', 'पाळ्यांमध्ये सुसंगती राहावी म्हणून तुमच्याही नोंदी तेवढ्याच त्रोटक ठेवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (130, 'B02-0001', NULL, 'B02', 'workplace_ethics', 3, 'Analyse', 'sjt', 'A fault indication appears on equipment you maintain, but the manual''s troubleshooting steps do not match what you see. What do you do?', 'तुम्ही देखभाल करत असलेल्या उपकरणावर दोष-सूचना येते, पण मॅन्युअलमधील तपासणी टप्पे दिसणाऱ्या स्थितीशी जुळत नाहीत. तुम्ही काय कराल?', 'When the evidence does not match the procedure, make safe, record facts and escalate. Guessing with resets or near-matching steps can hide or worsen the fault.', 'When the evidence does not match the procedure, make safe, record facts and escalate. Guessing with resets or near-matching steps can hide or worsen the fault.', 'पुरावा प्रक्रियेशी जुळत नसेल तर सुरक्षित करा, निरीक्षण नोंदवा व वरिष्ठांकडे न्या. रीसेट किंवा अंदाजे प्रक्रिया दोष लपवू किंवा वाढवू शकते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1097, 130, 1, 'Make it safe, record what you observe and escalate to the senior engineer or OEM', 'उपकरण सुरक्षित करा, निरीक्षणे नोंदवा व वरिष्ठ अभियंता किंवा OEM कडे पाठवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1098, 130, 2, 'Reset the equipment and keep it under observation for the rest of the shift', 'उपकरण रीसेट करा व उर्वरित पाळीत त्यावर लक्ष ठेवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1099, 130, 3, 'Try the closest matching procedure in the manual and note any differences', 'मॅन्युअलमधील सर्वात जवळची कार्यपद्धती वापरा व फरक नोंदवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1100, 130, 4, 'Hand it over to the next shift with a note, as it needs more time', 'अधिक वेळ लागणार म्हणून टिप्पणीसह पुढच्या पाळीकडे सोपवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (131, 'B02-0002', NULL, 'B02', 'workplace_ethics', 3, 'Analyse', 'sjt', 'Your section has two urgent requests and capacity for only one before the deadline. What is the best first step?', 'तुमच्या विभागाकडे दोन तातडीच्या विनंत्या आहेत पण मुदतीपूर्वी एकच पूर्ण करता येईल. सर्वोत्तम पहिला टप्पा कोणता?', 'Decide on impact (safety first, then service) and tell both requesters. Seniority or splitting effort does not decide priority.', 'Decide on impact (safety first, then service) and tell both requesters. Seniority or splitting effort does not decide priority.', 'परिणामावर (आधी सुरक्षा, मग सेवा) निर्णय घ्या व दोघांना कळवा. ज्येष्ठता किंवा दोन्ही एकत्र सुरू करणे यावरून प्राधान्य ठरत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1101, 131, 1, 'Compare the safety and service impact, decide, and inform both', 'सुरक्षा व सेवेवरील परिणामांची तुलना करा, निर्णय घ्या व दोघांना कळवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1102, 131, 2, 'Take up the request from the more senior officer and inform the other', 'अधिक वरिष्ठ अधिकाऱ्याची विनंती घ्या व दुसऱ्याला कळवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1103, 131, 3, 'Start both in parallel and complete whichever is ready first', 'दोन्ही एकाच वेळी सुरू करा व जे आधी तयार होईल ते पूर्ण करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1104, 131, 4, 'Refer both to your HoD and ask which one should be done first', 'दोन्ही HoD कडे पाठवा व आधी कोणते करायचे ते विचारा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (132, 'B03-0001', NULL, 'B03', 'workplace_ethics', 3, 'Apply', 'sjt', 'During peak hour a train is cancelled, a crowd builds up on the platform and some passengers start shouting at you. What do you do?', 'गर्दीच्या वेळी एक गाडी रद्द होते, प्लॅटफॉर्मवर गर्दी वाढते आणि काही प्रवासी तुमच्यावर ओरडू लागतात. तुम्ही काय कराल?', 'Calm, clear information and the crowd-control procedure reduce tension. False promises or removing passengers escalate it.', 'Calm, clear information and the crowd-control procedure reduce tension. False promises or removing passengers escalate it.', 'शांत राहून स्पष्ट माहिती देणे व गर्दी-नियंत्रण प्रक्रिया पाळल्याने तणाव कमी होतो. खोटे आश्वासन किंवा प्रवाशांना हटवणे परिस्थिती बिघडवते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1105, 132, 1, 'Stay calm, inform clearly, follow crowd-control steps and call the SCR', 'शांत रहा, स्पष्ट माहिती द्या, गर्दी-नियंत्रण टप्पे पाळा व SCR ला बोलवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1106, 132, 2, 'Move away from the angry group and manage the crowd from the other end', 'संतप्त गटापासून दूर जा व दुसऱ्या टोकावरून गर्दी हाताळा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1107, 132, 3, 'Promise them the next train will arrive in two or three minutes', 'पुढची गाडी दोन-तीन मिनिटांत येईल असे आश्वासन द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1108, 132, 4, 'Ask security staff to remove the passengers who are shouting', 'ओरडणाऱ्या प्रवाशांना बाहेर काढण्यास सुरक्षा कर्मचाऱ्यांना सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (133, 'B03-0002', NULL, 'B03', 'workplace_ethics', 3, 'Apply', 'sjt', 'During a simulator exercise, an unexpected combination of faults appears. What is the best response?', 'सिम्युलेटर सरावात अनपेक्षित दोषांचे संयोजन दिसते. सर्वोत्तम प्रतिसाद कोणता?', 'With multiple faults, deal with the most safety-critical one first and keep OCC informed, as you would in real service.', 'With multiple faults, deal with the most safety-critical one first and keep OCC informed, as you would in real service.', 'अनेक दोष असताना सर्वात सुरक्षा-महत्त्वाचा दोष आधी हाताळा व OCC ला कळवत रहा – प्रत्यक्ष सेवेतही असेच करावे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1109, 133, 1, 'Pause, handle the most safety-critical fault first, and inform OCC', 'थांबा, आधी सर्वात सुरक्षा-महत्त्वाचा दोष हाताळा व OCC ला कळवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1110, 133, 2, 'Deal with the faults in the order in which they appeared on the screen', 'दोष स्क्रीनवर ज्या क्रमाने दिसले त्याच क्रमाने हाताळा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1111, 133, 3, 'Act quickly from experience, then check the procedure afterwards', 'अनुभवाने पटकन कृती करा, नंतर कार्यपद्धती तपासा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1112, 133, 4, 'Stop and ask the instructor how to proceed with two faults together', 'थांबा व दोन दोष एकत्र कसे हाताळायचे ते प्रशिक्षकाला विचारा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (134, 'B04-0001', NULL, 'B04', 'workplace_ethics', 2, 'Apply', 'sjt', 'You realise that a measurement you recorded yesterday in the maintenance log was wrong. What do you do?', 'काल देखभाल नोंदवहीत नोंदवलेले मोजमाप चुकीचे होते हे तुमच्या लक्षात येते. तुम्ही काय कराल?', 'Records must stay honest and traceable: correct them through the laid-down procedure and inform the supervisor. Overwriting or ignoring an error damages integrity.', 'Records must stay honest and traceable: correct them through the laid-down procedure and inform the supervisor. Overwriting or ignoring an error damages integrity.', 'नोंदी प्रामाणिक व मागोवा घेता येतील अशा राहाव्यात: विहित पद्धतीने दुरुस्ती करा व पर्यवेक्षकाला कळवा. खाडाखोड किंवा दुर्लक्ष विश्वासार्हता कमी करते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1113, 134, 1, 'Correct it by the record-correction procedure and tell your supervisor', 'नोंद-दुरुस्ती कार्यपद्धतीनुसार दुरुस्त करा व पर्यवेक्षकाला सांगा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1114, 134, 2, 'Re-measure at the next scheduled inspection and record the new value then', 'पुढील नियोजित तपासणीत पुन्हा मोजा व तेव्हा नवे मूल्य नोंदवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1115, 134, 3, 'Correct the figure neatly in the log so the record looks right', 'नोंद बरोबर दिसावी म्हणून वहीत आकडा व्यवस्थित दुरुस्त करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1116, 134, 4, 'Leave it, because the difference is within the usual tolerance', 'फरक नेहमीच्या सहनशीलतेत असल्याने तसेच राहू द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (135, 'B04-0002', NULL, 'B04', 'workplace_ethics', 2, 'Apply', 'sjt', 'You promised a stakeholder a report by Friday, but you now see it will be a day late. What is best?', 'तुम्ही एका भागधारकाला शुक्रवारपर्यंत अहवाल देण्याचे वचन दिले होते, पण आता तो एक दिवस उशिरा होईल. काय सर्वोत्तम?', 'Telling people early with a firm new date lets them plan. Silent delay or a rushed, poor report both break trust.', 'Telling people early with a firm new date lets them plan. Silent delay or a rushed, poor report both break trust.', 'लवकर कळवून ठाम नवी तारीख दिल्यास इतरांना नियोजन करता येते. न कळवता उशीर किंवा घाईचा निकृष्ट अहवाल – दोन्ही विश्वास तोडतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1117, 135, 1, 'Tell them now, with the reason and a firm new date', 'त्यांना आताच कारण व निश्चित नवी तारीख सांगा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1118, 135, 2, 'Send the finished sections on Friday and the rest later', 'पूर्ण झालेले भाग शुक्रवारी पाठवा व उरलेले नंतर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1119, 135, 3, 'Work late on Thursday to finish it, even if quality drops', 'गुणवत्ता कमी झाली तरी गुरुवारी उशिरापर्यंत काम करून पूर्ण करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1120, 135, 4, 'Send it on Monday; one day will not make a difference', 'सोमवारी पाठवा; एका दिवसाने फरक पडणार नाही', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (136, 'B05-0001', NULL, 'B05', 'workplace_ethics', 3, 'Apply', 'sjt', 'A new technician in your team keeps making mistakes in a routine task. What is the best approach?', 'तुमच्या टीममधील नवीन तंत्रज्ञ एका नेहमीच्या कामात वारंवार चुका करतो. सर्वोत्तम पद्धत कोणती?', 'Demonstrate, observe, give specific feedback and follow up: this builds skill quickly. Removing the task or waiting for a course delays learning.', 'Demonstrate, observe, give specific feedback and follow up: this builds skill quickly. Removing the task or waiting for a course delays learning.', 'दाखवा, निरीक्षण करा, नेमका अभिप्राय द्या व पाठपुरावा करा – कौशल्य लवकर वाढते. काम काढून घेणे किंवा कोर्सची वाट पाहणे शिक्षण लांबवते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1121, 136, 1, 'Show the task, watch him do it, give specific feedback and check again in a week', 'काम करून दाखवा, त्याला करताना पहा, नेमका अभिप्राय द्या व आठवड्याने पुन्हा तपासा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1122, 136, 2, 'Nominate him for the next CoE course on the task and review afterwards', 'त्या कामावरील पुढील CoE अभ्यासक्रमासाठी नामनिर्देशन करा व नंतर आढावा घ्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1123, 136, 3, 'Pair him permanently with an experienced technician for that task', 'त्या कामासाठी त्याला कायमस्वरूपी अनुभवी तंत्रज्ञासोबत जोडा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1124, 136, 4, 'Give the task to someone else until he gains more experience', 'त्याला अधिक अनुभव येईपर्यंत ते काम दुसऱ्याला द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (137, 'B05-0002', NULL, 'B05', 'workplace_ethics', 3, 'Apply', 'sjt', 'Two experienced staff in your team are reluctant to share their troubleshooting knowledge with juniors. What do you do?', 'तुमच्या टीममधील दोन अनुभवी कर्मचारी आपले दोष-निवारण ज्ञान कनिष्ठांना देण्यास नाखूष आहेत. तुम्ही काय कराल?', 'Recognising experts and making mentoring part of their role motivates sharing. Documents or outside courses do not pass on hands-on troubleshooting skill.', 'Recognising experts and making mentoring part of their role motivates sharing. Documents or outside courses do not pass on hands-on troubleshooting skill.', 'तज्ज्ञांना मान देऊन मार्गदर्शन त्यांच्या भूमिकेचा भाग केल्यास ज्ञान वाटण्यास प्रेरणा मिळते. कागद किंवा बाहेरचे प्रशिक्षण प्रत्यक्ष दोषनिवारण कौशल्य देत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1125, 137, 1, 'Recognise their expertise and make mentoring part of their role', 'त्यांच्या कौशल्याची दखल घ्या व मार्गदर्शन त्यांच्या भूमिकेचा भाग करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1126, 137, 2, 'Ask them to write their methods down so juniors can read them', 'कनिष्ठांना वाचता यावे म्हणून त्यांच्या पद्धती लिहून ठेवण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1127, 137, 3, 'Arrange outside training for the juniors instead', 'त्याऐवजी कनिष्ठांसाठी बाहेरील प्रशिक्षणाची व्यवस्था करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1128, 137, 4, 'Raise it in their annual appraisal as a development point', 'वार्षिक मूल्यांकनात विकासाचा मुद्दा म्हणून नोंदवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (138, 'B06-0001', NULL, 'B06', 'workplace_ethics', 3, 'Apply', 'sjt', 'You must plan a week of preventive maintenance while two of your staff are on leave. What is the best first step?', 'तुमचे दोन कर्मचारी रजेवर असताना एका आठवड्याच्या प्रतिबंधात्मक देखभालीचे नियोजन करायचे आहे. सर्वोत्तम पहिला टप्पा कोणता?', 'Plan from safety and due dates, match work to people and blocks, and agree any deferrals. Overtime or quick wins ignore the risk.', 'Plan from safety and due dates, match work to people and blocks, and agree any deferrals. Overtime or quick wins ignore the risk.', 'सुरक्षा व देय तारखेनुसार नियोजन करा, काम कर्मचारी व ब्लॉकशी जुळवा व पुढे ढकलण्यास मंजुरी घ्या. ओव्हरटाइम किंवा सोपी कामे आधी करणे धोक्याकडे दुर्लक्ष करते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1129, 138, 1, 'Rank tasks by safety and due date, fit them to staff and blocks, agree deferrals', 'सुरक्षा व देय तारखेनुसार कामांचा क्रम लावा, कर्मचारी व ब्लॉकशी जुळवा, पुढे ढकलण्यास मान्यता घ्या', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1130, 138, 2, 'Ask for overtime so the remaining staff can cover the full week''s schedule', 'उर्वरित कर्मचाऱ्यांना संपूर्ण आठवड्याचे वेळापत्रक पूर्ण करता यावे म्हणून जादा वेळ मागा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1131, 138, 3, 'Do the tasks that are quickest to finish first, to show progress', 'प्रगती दिसावी म्हणून सर्वात लवकर होणारी कामे आधी करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1132, 138, 4, 'Postpone the whole week''s schedule until both staff return', 'दोघे परत येईपर्यंत संपूर्ण आठवड्याचे वेळापत्रक पुढे ढकला', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (139, 'B06-0002', NULL, 'B06', 'workplace_ethics', 2, 'Apply', 'sjt', 'A file needs inputs from three sections within ten days. How do you organise it?', 'एका फाइलसाठी दहा दिवसांत तीन विभागांचे इनपुट हवे आहेत. तुम्ही ते कसे आयोजित कराल?', 'Specific questions with due dates and tracking get usable inputs on time. A general email or a last-day meeting leaves no time to follow up.', 'Specific questions with due dates and tracking get usable inputs on time. A general email or a last-day meeting leaves no time to follow up.', 'नेमके प्रश्न, मुदत व पाठपुरावा यामुळे उपयुक्त माहिती वेळेत मिळते. सर्वसाधारण ई-मेल किंवा शेवटच्या दिवशी बैठक घेतल्यास पाठपुराव्याला वेळ उरत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1133, 139, 1, 'Send each section specific questions and a due date, then track replies', 'प्रत्येक विभागाला नेमके प्रश्न व देय तारीख पाठवा, मग उत्तरांचा मागोवा घ्या', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1134, 139, 2, 'Send one general email to all three asking for inputs within ten days', 'दहा दिवसांत इनपुट मागणारा एकच सर्वसाधारण ई-मेल तिघांना पाठवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1135, 139, 3, 'Draft the inputs yourself and ask each section only to confirm them', 'इनपुट स्वतः तयार करा व प्रत्येक विभागाला फक्त पुष्टी करण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1136, 139, 4, 'Call a meeting of all three sections on the ninth day', 'नवव्या दिवशी तिन्ही विभागांची बैठक बोलवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (140, 'B07-0001', NULL, 'B07', 'workplace_ethics', 3, 'Apply', 'sjt', 'A residents'' group complains about night-time noise from viaduct maintenance near their building. What is the best response?', 'रहिवासी गट त्यांच्या इमारतीजवळील व्हायाडक्ट देखभालीच्या रात्रीच्या आवाजाबद्दल तक्रार करतो. सर्वोत्तम प्रतिसाद कोणता?', 'Meeting residents, explaining and acting to reduce noise builds goodwill. A formal reply or passing them to another office does not address the concern.', 'Meeting residents, explaining and acting to reduce noise builds goodwill. A formal reply or passing them to another office does not address the concern.', 'रहिवाशांना भेटून कारण सांगणे व आवाज कमी करण्याचे उपाय करणे सद्भावना वाढवते. औपचारिक उत्तर किंवा दुसऱ्या कार्यालयाकडे पाठवणे प्रश्न सोडवत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1137, 140, 1, 'Meet them, explain why night work is needed, share the schedule, cut noise', 'त्यांना भेटा, रात्रीचे काम का आवश्यक ते सांगा, वेळापत्रक द्या, आवाज कमी करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1138, 140, 2, 'Send a written reply explaining that metro maintenance is permitted at night', 'मेट्रो देखभालीला रात्री परवानगी असल्याचे लेखी उत्तर पाठवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1139, 140, 3, 'Shift the noisiest work to daytime blocks, even if it affects service', 'सेवेवर परिणाम झाला तरी सर्वात आवाजाचे काम दिवसाच्या ब्लॉकमध्ये हलवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1140, 140, 4, 'Refer the group to the local municipal office for a decision', 'निर्णयासाठी गटाला स्थानिक महानगरपालिका कार्यालयाकडे पाठवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (141, 'B07-0002', NULL, 'B07', 'workplace_ethics', 3, 'Apply', 'sjt', 'A partner agency is delaying a permission your project needs next month. What is the best approach?', 'भागीदार संस्था तुमच्या प्रकल्पाला पुढील महिन्यात लागणारी परवानगी देण्यास उशीर करत आहे. सर्वोत्तम पद्धत कोणती?', 'Understanding the partner''s concerns and supplying what they need resolves most delays. Escalating first strains the relationship; working without permission is a violation.', 'Understanding the partner''s concerns and supplying what they need resolves most delays. Escalating first strains the relationship; working without permission is a violation.', 'भागीदार संस्थेच्या अडचणी समजून आवश्यक माहिती दिल्यास बहुतेक विलंब सुटतात. थेट वरिष्ठांकडे जाणे संबंध ताणते; परवानगीशिवाय काम सुरू करणे नियमभंग आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1141, 141, 1, 'Understand their concerns, supply what they need, agree a timeline', 'त्यांच्या अडचणी समजून घ्या, आवश्यक माहिती द्या, वेळापत्रक ठरवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1142, 141, 2, 'Escalate it at once to the top management of both organisations', 'दोन्ही संस्थांच्या सर्वोच्च व्यवस्थापनाकडे लगेच पाठवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1143, 141, 3, 'Send weekly reminder letters until the permission is issued', 'परवानगी मिळेपर्यंत दर आठवड्याला स्मरणपत्रे पाठवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1144, 141, 4, 'Start the preparatory work and regularise it after permission comes', 'पूर्वतयारीचे काम सुरू करा व परवानगी आल्यावर नियमित करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (142, 'D01-0001', NULL, 'D01', 'train_ops', 3, 'Apply', 'single', 'During a signalling failure your train is held at a stop signal. OCC has not answered the train radio for two minutes and the line ahead looks clear. What should you do?', 'सिग्नलिंग बिघाडात तुमची गाडी थांबा-सिग्नलवर उभी आहे. दोन मिनिटांपासून OCC ट्रेन रेडिओला उत्तर देत नाही आणि पुढील मार्ग मोकळा दिसतो. तुम्ही काय करावे?', 'A stop signal may be passed only on proper authority from the controller. A clear-looking line, another station''s permission or a mode change is not authority.', 'A stop signal may be passed only on proper authority from the controller. A clear-looking line, another station''s permission or a mode change is not authority.', 'थांबा-सिग्नल फक्त नियंत्रकाच्या योग्य अधिकारानेच ओलांडता येतो. मोकळा दिसणारा मार्ग, दुसऱ्या स्थानकाची परवानगी किंवा मोड बदल हा अधिकार नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1145, 142, 1, 'Stay stationary and contact OCC by the other means laid down', 'गाडी थांबवून ठेवा व नियमात दिलेल्या इतर मार्गाने OCC शी संपर्क करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1146, 142, 2, 'Move at restricted speed to the next signal, as the line is clear', 'मार्ग मोकळा असल्याने प्रतिबंधित वेगाने पुढील सिग्नलपर्यंत जा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1147, 142, 3, 'Ask the Station Controller behind you for permission to proceed', 'मागील स्थानकाच्या स्टेशन कंट्रोलरकडून पुढे जाण्याची परवानगी घ्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1148, 142, 4, 'Switch to restricted manual mode, since ATP will limit the speed', 'प्रतिबंधित मॅन्युअल मोडमध्ये जा, कारण ATP वेग मर्यादित ठेवेल', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (143, 'D01-0002', NULL, 'D01', 'train_ops', 3, 'Apply', 'single', 'A 30 km/h temporary speed restriction applies from km 12.400 to km 12.600. Your train is 130 m long. Where must the front of the train be before you accelerate?', 'km 12.400 ते km 12.600 दरम्यान 30 km/h तात्पुरती वेग-मर्यादा आहे. तुमची गाडी 130 मीटर लांब आहे. वेग वाढवण्यापूर्वी गाडीचे पुढचे टोक कोठे असले पाहिजे?', 'The whole train must clear the restriction: 12.600 + 0.130 = 12.730.', 'The whole train must clear the restriction: 12.600 + 0.130 = 12.730.', 'संपूर्ण गाडीने मर्यादा पार केली पाहिजे: 12.600 + 0.130 = 12.730.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1149, 143, 1, 'At km 12.730', 'km 12.730 वर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1150, 143, 2, 'At km 12.600', 'km 12.600 वर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1151, 143, 3, 'At km 12.530', 'km 12.530 वर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1152, 143, 4, 'At km 12.650', 'km 12.650 वर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (144, 'D01-0003', NULL, 'D01', 'train_ops', 2, 'Understand', 'single', 'A maintenance block is in force in a section. Who may allow a train to enter that section?', 'एका विभागात देखभाल ब्लॉक लागू आहे. त्या विभागात गाडीला प्रवेश करू देण्याची परवानगी कोण देऊ शकतो?', 'Only the traffic controller who granted the block can cancel it and admit trains. The engineer finishing work must first hand the section back.', 'Only the traffic controller who granted the block can cancel it and admit trains. The engineer finishing work must first hand the section back.', 'ब्लॉक दिलेला वाहतूक नियंत्रकच तो रद्द करून गाडी सोडू शकतो. काम संपलेल्या अभियंत्याने आधी विभाग परत सोपवावा लागतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1153, 144, 1, 'The traffic controller, after the block is cancelled', 'ब्लॉक रद्द झाल्यानंतर वाहतूक नियंत्रक', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1154, 144, 2, 'The engineer-in-charge, once his work is finished', 'काम संपल्यावर प्रभारी अभियंता', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1155, 144, 3, 'The Station Controller of the next station ahead', 'पुढील स्थानकाचा स्टेशन कंट्रोलर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1156, 144, 4, 'The train operator, after a visual check of the line', 'मार्गाची नजरेने तपासणी केल्यावर चालक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (145, 'D02-0001', NULL, 'D02', 'train_ops', 2, 'Understand', 'single', 'Which statement about CBTC automatic train operation (ATO) mode is correct?', 'CBTC च्या ऑटोमॅटिक ट्रेन ऑपरेशन (ATO) मोडबद्दल कोणते विधान बरोबर आहे?', 'In ATO the train drives and stops itself within ATP limits. The operator monitors and closes doors; ATP is never relaxed.', 'In ATO the train drives and stops itself within ATP limits. The operator monitors and closes doors; ATP is never relaxed.', 'ATO मध्ये गाडी ATP मर्यादेत स्वतः चालते व थांबते; ऑपरेटर देखरेख करतो व दरवाजे बंद करतो. ATP कधीही शिथिल होत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1157, 145, 1, 'The train runs and stops automatically under ATP, while the operator monitors', 'ATP अंतर्गत गाडी आपोआप धावते व थांबते, तर चालक निरीक्षण करतो', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1158, 145, 2, 'The train runs automatically, but the operator may exceed limits if late', 'गाडी आपोआप धावते, पण उशीर झाल्यास चालक मर्यादा ओलांडू शकतो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1159, 145, 3, 'The operator controls the speed, and ATO only shows an advisory speed', 'चालक वेग नियंत्रित करतो आणि ATO फक्त सुचवलेला वेग दाखवते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1160, 145, 4, 'ATP protection is relaxed between stations to give a smoother ride', 'प्रवास सुरळीत व्हावा म्हणून स्थानकांदरम्यान ATP संरक्षण शिथिल होते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (146, 'D02-0002', NULL, 'D02', 'train_ops', 3, 'Apply', 'sjt', 'At departure, the DMI shows one door not closed and locked. Platform staff say the door looks closed. What should you do?', 'निघताना DMI वर एक दरवाजा ''बंद व लॉक नाही'' असे दिसते. प्लॅटफॉर्म कर्मचारी म्हणतात दरवाजा बंद दिसतो. तुम्ही काय कराल?', 'The DMI ''door not proven'' must be treated as real until checked. Follow the door-fault procedure with OCC. Bypassing on a visual impression risks a passenger fall.', 'The DMI ''door not proven'' must be treated as real until checked. Follow the door-fault procedure with OCC. Bypassing on a visual impression risks a passenger fall.', 'DMI वरील ''दरवाजा बंद नाही'' संकेत तपासेपर्यंत खरा मानावा. OCC सह दरवाजा-दोष प्रक्रिया पाळा. केवळ दिसण्यावरून बायपास केल्यास प्रवासी पडण्याचा धोका.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1161, 146, 1, 'Follow the door-fault procedure: inform OCC, check and isolate as per rules', 'दरवाजा-बिघाड कार्यपद्धती पाळा: OCC ला कळवा, तपासा व नियमानुसार वेगळा करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1162, 146, 2, 'Re-open and close all doors once more before telling anyone', 'कोणालाही सांगण्यापूर्वी सर्व दरवाजे पुन्हा एकदा उघडून बंद करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1163, 146, 3, 'Detrain all passengers at this platform and ask for a relief train', 'या प्लॅटफॉर्मवर सर्व प्रवासी उतरवा व पर्यायी गाडी मागवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1164, 146, 4, 'Use the door bypass to depart, as platform staff confirm it is shut', 'प्लॅटफॉर्म कर्मचाऱ्यांनी खात्री दिल्याने डोअर-बायपास वापरून निघा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (147, 'D02-0003', NULL, 'D02', 'train_ops', 1, 'Remember', 'truefalse', 'In ATO mode the train operator must still watch the line ahead and the platform.', 'ATO मोडमध्येही चालकाने पुढील मार्ग व प्लॅटफॉर्मवर लक्ष ठेवलेच पाहिजे.', 'ATO automates driving, not vigilance. The operator must watch for obstructions and platform hazards.', 'ATO automates driving, not vigilance. The operator must watch for obstructions and platform hazards.', 'ATO चालवणे स्वयंचलित करते, सतर्कता नाही. ऑपरेटरने अडथळे व प्लॅटफॉर्मवरील धोके पाहत राहावे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1165, 147, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1166, 147, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (148, 'D02-0004', NULL, 'D02', 'train_ops', 3, 'Understand', 'single', 'What does restricted manual (RM) driving mode generally mean?', 'रिस्ट्रिक्टेड मॅन्युअल (RM) चालन मोड म्हणजे सामान्यतः काय?', 'RM is a degraded mode: the operator drives by sight with a low speed cap and reduced ATP protection.', 'RM is a degraded mode: the operator drives by sight with a low speed cap and reduced ATP protection.', 'RM हा कमी-संरक्षण मोड आहे: ऑपरेटर नजरेने, कमी वेग-मर्यादेत चालवतो व ATP संरक्षण मर्यादित असते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1167, 148, 1, 'Manual driving with a low capped speed and limited protection', 'कमी कमाल वेग व मर्यादित संरक्षणासह हाताने चालवणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1168, 148, 2, 'Manual driving at line speed, with full ATP supervision', 'पूर्ण ATP देखरेखीखाली मार्ग-वेगाने हाताने चालवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1169, 148, 3, 'Automatic driving with the doors controlled by the operator', 'चालक दरवाजे नियंत्रित करतो अशा प्रकारचे स्वयंचलित चालन', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1170, 148, 4, 'A depot-only mode used for coupling and washing trains', 'जोडणी व धुलाईसाठी फक्त डेपोमधील मोड', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (149, 'D03-0001', NULL, 'D03', 'train_ops', 3, 'Analyse', 'single', 'At station opening, the fire alarm panel shows a ''fault'' (not an alarm) on one smoke-detector loop. What should the Station Controller do?', 'स्थानक उघडताना अग्नि-इशारा पॅनेलवर एका धूर-शोधक लूपवर ''दोष'' (इशारा नव्हे) दिसतो. स्टेशन कंट्रोलरने काय करावे?', 'A loop fault means part of the station may not detect fire. The defect must be logged and repaired, and the area watched meanwhile.', 'A loop fault means part of the station may not detect fire. The defect must be logged and repaired, and the area watched meanwhile.', 'लूप-दोष म्हणजे स्थानकाच्या काही भागात आग ओळखली जाणार नाही. दोष नोंदवून दुरुस्त केला पाहिजे व तोपर्यंत त्या भागावर लक्ष ठेवले पाहिजे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1171, 149, 1, 'Record it, inform E&M and OCC, and open with extra watch on that area', 'नोंद करा, E&M व OCC ला कळवा आणि त्या भागावर जादा लक्ष ठेवून उघडा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1172, 149, 2, 'Keep the station closed until the loop fault has been repaired', 'लूपमधील दोष दुरुस्त होईपर्यंत स्थानक बंद ठेवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1173, 149, 3, 'Silence and reset the panel, and open if the fault clears', 'पॅनेल शांत करून रीसेट करा आणि दोष गेल्यास उघडा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1174, 149, 4, 'Open normally, since a fault is not the same as a fire alarm', 'सामान्यपणे उघडा, कारण दोष म्हणजे अग्नि-इशारा नव्हे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (150, 'D03-0002', NULL, 'D03', 'train_ops', 2, 'Remember', 'multi', 'Which of these belong to the station opening checks?', 'यापैकी कोणत्या तपासण्या स्थानक उघडण्याच्या तपासण्यांत येतात?', 'Opening checks cover safety and passenger systems needed from the first train. Monthly brake tests and revenue reconciliation are not daily opening tasks.', 'Opening checks cover safety and passenger systems needed from the first train. Monthly brake tests and revenue reconciliation are not daily opening tasks.', 'उघडण्याच्या तपासण्यांत पहिल्या गाडीपासून लागणाऱ्या सुरक्षा व प्रवासी प्रणाली येतात. मासिक ब्रेक चाचणी व महसूल ताळमेळ ही रोजची कामे नाहीत.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1175, 150, 1, 'Platforms and track area clear of obstructions', 'प्लॅटफॉर्म व रुळाचा भाग अडथळामुक्त', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1176, 150, 2, 'Fire alarm panel healthy', 'अग्नि-इशारा पॅनेल सुस्थितीत', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1177, 150, 3, 'AFC gates and ticket machines in service', 'AFC गेट व तिकीट यंत्रे सेवेत', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1178, 150, 4, 'PA and passenger displays working', 'PA व प्रवासी प्रदर्शक कार्यरत', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1179, 150, 5, 'Monthly escalator brake test completed', 'एस्केलेटरची मासिक ब्रेक-चाचणी पूर्ण', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1180, 150, 6, 'Previous month''s revenue reconciled with AFC central system', 'मागील महिन्याचा महसूल AFC केंद्रीय प्रणालीशी जुळवलेला', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (151, 'D03-0003', NULL, 'D03', 'train_ops', 2, 'Remember', 'single', 'What does pressing the Emergency Stop Plunger (ESP) on a platform do?', 'प्लॅटफॉर्मवरील इमर्जन्सी स्टॉप प्लंजर (ESP) दाबल्यावर काय होते?', 'The ESP stops train movement into and out of that platform (for example, when someone falls onto the track). It does not cut traction for the whole line.', 'The ESP stops train movement into and out of that platform (for example, when someone falls onto the track). It does not cut traction for the whole line.', 'ESP त्या प्लॅटफॉर्मवर येणारी-जाणारी गाडी थांबवतो (उदा. कोणी रुळावर पडल्यास). तो संपूर्ण मार्गाचा ट्रॅक्शन पुरवठा बंद करत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1181, 151, 1, 'Stops trains entering or leaving that platform', 'त्या प्लॅटफॉर्मवर येणाऱ्या किंवा जाणाऱ्या गाड्या थांबतात', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1182, 151, 2, 'Switches off traction power on the whole line', 'संपूर्ण मार्गावरील ट्रॅक्शन वीज बंद होते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1183, 151, 3, 'Opens all platform screen doors at once', 'सर्व प्लॅटफॉर्म स्क्रीन दरवाजे एकदम उघडतात', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1184, 151, 4, 'Stops the escalators serving that platform', 'त्या प्लॅटफॉर्मचे एस्केलेटर थांबतात', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (152, 'D03-0004', NULL, 'D03', 'train_ops', 1, 'Remember', 'single', 'This sound plays on the platform and in the train. What does it tell passengers?', 'हा आवाज प्लॅटफॉर्मवर व गाडीत वाजतो. तो प्रवाशांना काय सांगतो?', 'This door chime warns passengers that the doors are about to close.', 'This door chime warns passengers that the doors are about to close.', 'ही दरवाजा-घंटी दरवाजे बंद होणार असल्याचा इशारा देते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1185, 152, 1, 'Doors are about to close', 'दरवाजे बंद होणार आहेत', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1186, 152, 2, 'The train will not stop here', 'गाडी इथे थांबणार नाही', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1187, 152, 3, 'Evacuate the station now', 'आता स्थानक रिकामे करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1188, 152, 4, 'Next train is the last one', 'पुढची गाडी शेवटची आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (153, 'D03-0005', NULL, 'D03', 'train_ops', 3, 'Analyse', 'sjt', 'After a cricket match at a nearby stadium, the platform is filling faster than trains can clear it. What is the most effective first step?', 'जवळच्या स्टेडियममधील क्रिकेट सामन्यानंतर प्लॅटफॉर्मवर, गाड्या नेऊ शकतात त्यापेक्षा वेगाने गर्दी भरत आहे. सर्वात परिणामकारक पहिला टप्पा कोणता?', 'Control the inflow upstream, before the platform; announcements help but do not stop the build-up; free gates increase the flow onto the platform.', 'Control the inflow upstream, before the platform; announcements help but do not stop the build-up; free gates increase the flow onto the platform.', 'प्लॅटफॉर्मपूर्वीच प्रवेश नियंत्रित करा; उद्घोषणांनी मदत होते पण गर्दी थांबत नाही; मुक्त गेटमुळे प्लॅटफॉर्मवर गर्दी अधिक वाढते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1189, 153, 1, 'Regulate entry at the gates and stairs, and ask OCC to add or hold trains', 'गेट व जिन्यावर प्रवेश नियंत्रित करा व OCC ला जादा गाड्या किंवा थांबा मागा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1190, 153, 2, 'Make repeated PA announcements asking passengers to spread along the platform', 'प्लॅटफॉर्मवर पसरून उभे राहण्यासाठी वारंवार PA उद्घोषणा करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1191, 153, 3, 'Stop issuing tokens and QR tickets until the crowd reduces', 'गर्दी कमी होईपर्यंत टोकन व QR तिकीट देणे थांबवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1192, 153, 4, 'Set the AFC gates to free mode so people move through faster', 'लोक लवकर पुढे जावेत म्हणून AFC गेट मुक्त मोडमध्ये ठेवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (154, 'D04-0001', NULL, 'D04', 'station_control', 3, 'Apply', 'numeric', 'A line''s round trip, including turnaround time at both terminals, takes 66 minutes, and 11 trains are in service. What headway can be run (minutes)?', 'दोन्ही टर्मिनलवरील वळणाच्या वेळेसह एका मार्गाची फेरी 66 मिनिटांची आहे आणि 11 गाड्या सेवेत आहेत. किती मिनिटांचा हेडवे देता येईल?', 'Headway = round-trip time ÷ trains in service = 66 ÷ 11 = 6 minutes.', 'Headway = round-trip time ÷ trains in service = 66 ÷ 11 = 6 minutes.', 'हेडवे = फेरीचा वेळ ÷ सेवेतील गाड्या = 66 ÷ 11 = 6 मिनिटे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (155, 'D04-0002', NULL, 'D04', 'station_control', 3, 'Understand', 'single', 'A train is delayed 4 minutes at mid-line in the peak, and nothing is done. What usually happens next?', 'गर्दीच्या वेळी एक गाडी मार्गाच्या मध्यात 4 मिनिटे उशिरा होते आणि काहीही केले जात नाही. पुढे सहसा काय होते?', 'Delays grow into bunching: the late train meets more waiting passengers, dwells longer and falls further behind.', 'Delays grow into bunching: the late train meets more waiting passengers, dwells longer and falls further behind.', 'विलंबातून गाड्यांची गर्दी (bunching) होते: उशिराच्या गाडीला अधिक प्रवासी मिळतात, ती जास्त थांबते व आणखी मागे पडते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1193, 155, 1, 'Its gap grows, it gets later and the train behind catches up', 'त्याच्यापुढील अंतर वाढते, तो आणखी उशिरा होतो व मागची गाडी जवळ येते', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1194, 155, 2, 'The delay stays the same until it is absorbed at the terminal', 'टर्मिनलवर भरून निघेपर्यंत विलंब तेवढाच राहतो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1195, 155, 3, 'All following trains are delayed by the same 4 minutes', 'मागच्या सर्व गाड्यांना तेवढाच 4 मिनिटांचा विलंब होतो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1196, 155, 4, 'ATS recovers the time automatically within two stations', 'ATS दोन स्थानकांत वेळ आपोआप भरून काढते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (156, 'D04-0003', NULL, 'D04', 'station_control', 2, 'Understand', 'single', 'After a delay, the controller holds some following trains briefly at stations. Why?', 'विलंबानंतर नियंत्रक मागच्या काही गाड्यांना स्थानकांवर थोडा वेळ थांबवतो. का?', 'Holding following trains for a short time evens out the gaps so that platform crowds and dwell times do not keep growing (headway regulation).', 'Holding following trains for a short time evens out the gaps so that platform crowds and dwell times do not keep growing (headway regulation).', 'मागच्या गाड्या थोड्या रोखल्याने अंतर समान होते आणि प्लॅटफॉर्मवरील गर्दी व थांबण्याचा वेळ वाढत जात नाही (हेडवे नियमन).', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1197, 156, 1, 'To even out the gaps and restore a regular headway', 'अंतर समान करून नियमित हेडवे पुन्हा आणण्यासाठी', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1198, 156, 2, 'To give the delayed train''s crew a rest break', 'उशिराच्या गाडीच्या कर्मचाऱ्यांना विश्रांती देण्यासाठी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1199, 156, 3, 'To reduce the traction energy used in the peak', 'गर्दीच्या वेळी ट्रॅक्शन ऊर्जा कमी करण्यासाठी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1200, 156, 4, 'To let passengers on platforms buy tickets', 'प्लॅटफॉर्मवरील प्रवाशांना तिकीट घेता यावे म्हणून', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (157, 'D05-0001', NULL, 'D05', 'station_control', 3, 'Analyse', 'sjt', 'Peak hour: a train is held between stations by a signalling failure and passengers on your platform are getting agitated. As Station Controller, what do you do first?', 'गर्दीची वेळ: सिग्नलिंग बिघाडामुळे गाडी दोन स्थानकांदरम्यान थांबली आहे आणि प्लॅटफॉर्मवरील प्रवासी अस्वस्थ होत आहेत. स्टेशन कंट्रोलर म्हणून तुम्ही प्रथम काय कराल?', 'Coordinated information plus crowd regulation keeps the station safe; the SCR must not be left unmanned; silence makes agitation worse.', 'Coordinated information plus crowd regulation keeps the station safe; the SCR must not be left unmanned; silence makes agitation worse.', 'समन्वित माहिती व गर्दी नियमनामुळे स्थानक सुरक्षित राहते; SCR रिकामा ठेवू नये; मौनामुळे अस्वस्थता वाढते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1201, 157, 1, 'Coordinate with OCC and regulate entry at the AFC gates', 'OCC शी समन्वय साधा व AFC गेटवर प्रवेश नियंत्रित करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1202, 157, 2, 'Make regular PA announcements with the expected delay', 'अपेक्षित विलंबासह नियमित PA उद्घोषणा करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1203, 157, 3, 'Leave the SCR and calm passengers on the platform yourself', 'SCR सोडून स्वतः प्लॅटफॉर्मवर प्रवाशांना शांत करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1204, 157, 4, 'Wait for OCC instructions before making any announcement', 'कोणतीही उद्घोषणा करण्यापूर्वी OCC च्या सूचनांची वाट पहा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (158, 'D05-0002', NULL, 'D05', 'station_control', 3, 'Apply', 'sequence', 'Put the first actions for a confirmed fire at a station in the correct order.', 'स्थानकावर आग निश्चित झाल्यावर पहिल्या कृती योग्य क्रमाने लावा.', 'Alarm and OCC first, then the announcement, free exit through the gates, the evacuation sweep, and only then ''station clear''.', 'Alarm and OCC first, then the announcement, free exit through the gates, the evacuation sweep, and only then ''station clear''.', 'आधी अलार्म व OCC, मग उद्घोषणा, गेट मोकळे, सर्व भाग तपासून बाहेर काढणे, आणि शेवटी ''स्थानक रिकामे'' कळवणे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (159, 'D05-0003', NULL, 'D05', 'station_control', 2, 'Understand', 'truefalse', 'During a fire evacuation, lifts may be used for passengers with reduced mobility if the fire is on another floor.', 'आग दुसऱ्या मजल्यावर असल्यास, आग-निर्वासनाच्या वेळी हालचाल-मर्यादा असलेल्या प्रवाशांसाठी लिफ्ट वापरता येतात.', 'Ordinary lifts must not be used in a fire; passengers with reduced mobility are helped by staff to refuge areas or down the stairs, as per the evacuation plan.', 'Ordinary lifts must not be used in a fire; passengers with reduced mobility are helped by staff to refuge areas or down the stairs, as per the evacuation plan.', 'आगीच्या वेळी सामान्य लिफ्ट वापरू नयेत; हालचाल-मर्यादा असलेल्या प्रवाशांना निर्वासन योजनेनुसार कर्मचारी आश्रय-क्षेत्रात किंवा जिन्याने खाली नेतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1205, 159, 1, 'True', 'बरोबर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1206, 159, 2, 'False', 'चूक', 1, '');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (160, 'D05-0004', NULL, 'D05', 'station_control', 3, 'Analyse', 'single', 'Read the passage. Why did the Station Controller ask OCC to hold the approaching train?', 'उतारा वाचा. स्टेशन कंट्रोलरने येणारी गाडी थांबवण्याची विनंती OCC ला का केली?', 'Holding the train stops passengers being let out onto a platform with fire and smoke.', 'Holding the train stops passengers being let out onto a platform with fire and smoke.', 'गाडी थांबवल्याने आग व धूर असलेल्या प्लॅटफॉर्मवर प्रवासी उतरत नाहीत.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1207, 160, 1, 'So that passengers would not alight onto a platform with a fire', 'आग असलेल्या प्लॅटफॉर्मवर प्रवासी उतरू नयेत म्हणून', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1208, 160, 2, 'So that the train crew could help to put out the fire', 'गाडीचे कर्मचारी आग विझवण्यास मदत करू शकावेत म्हणून', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1209, 160, 3, 'Because OCC must approve every fire announcement first', 'कारण प्रत्येक आग-उद्घोषणेला आधी OCC ची मंजुरी लागते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1210, 160, 4, 'Because smoke can trip the traction supply of the section', 'कारण धुरामुळे विभागाचा ट्रॅक्शन पुरवठा ट्रिप होऊ शकतो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (161, 'D05-0005', NULL, 'D05', 'station_control', 2, 'Apply', 'numeric', 'Read the passage. For how many minutes was platform 2 out of use (from 08:42 until it reopened)?', 'उतारा वाचा. प्लॅटफॉर्म 2 किती मिनिटे वापराबाहेर होता (08:42 पासून पुन्हा सुरू होईपर्यंत)?', 'From 08:42 to 09:05 is 23 minutes.', 'From 08:42 to 09:05 is 23 minutes.', '08:42 ते 09:05 म्हणजे 23 मिनिटे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (162, 'D05-0006', NULL, 'D05', 'station_control', 3, 'Analyse', 'multi', 'Read the passage. Which details must the incident report include?', 'उतारा वाचा. घटना अहवालात कोणते तपशील असले पाहिजेत?', 'An incident report records times, actions and the effect on service. Passengers'' personal details and minor costs are not part of it.', 'An incident report records times, actions and the effect on service. Passengers'' personal details and minor costs are not part of it.', 'घटना-अहवालात वेळा, केलेली कृती व सेवेवरील परिणाम नोंदवतात. प्रवाशांचे वैयक्तिक तपशील व किरकोळ खर्च त्यात नसतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1211, 162, 1, 'Times of detection, extinguishing and reopening', 'शोध, विझवणे व पुन्हा सुरू होण्याच्या वेळा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1212, 162, 2, 'Action taken and the extinguisher type used', 'केलेली कृती व वापरलेल्या अग्निशामकाचा प्रकार', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1213, 162, 3, 'Effect on train service, with delays', 'गाडी सेवेवरील परिणाम व विलंब', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1214, 162, 4, 'Names and phone numbers of passengers on the platform', 'प्लॅटफॉर्मवरील प्रवाशांची नावे व फोन क्रमांक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1215, 162, 5, 'The cost of replacing the waste bin', 'कचरापेटी बदलण्याचा खर्च', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (163, 'D06-0001', NULL, 'D06', 'station_control', 2, 'Apply', 'single', 'A passenger''s QR ticket is rejected at the entry gate. What should station staff do?', 'प्रवाशाचे QR तिकीट प्रवेश गेटवर नाकारले जाते. स्थानक कर्मचाऱ्यांनी काय करावे?', 'The TOM analysis shows why the ticket was rejected (for example, already used or expired), so it can be resolved by the AFC rules. Free entry or a free ticket causes revenue loss.', 'The TOM analysis shows why the ticket was rejected (for example, already used or expired), so it can be resolved by the AFC rules. Free entry or a free ticket causes revenue loss.', 'TOM विश्लेषणाने तिकीट का नाकारले (उदा. आधी वापरले, मुदत संपली) ते कळते व AFC नियमांनुसार सोडवता येते. मोफत प्रवेश किंवा तिकीट महसूल-तोटा करतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1216, 163, 1, 'Analyse the ticket at the TOM and resolve it as per AFC rules', 'TOM वर तिकीट तपासा व AFC नियमांनुसार प्रश्न सोडवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1217, 163, 2, 'Let the passenger in by the staff gate and note the ticket number', 'कर्मचारी गेटने प्रवाशाला आत सोडा व तिकीट क्रमांक नोंदवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1218, 163, 3, 'Issue a fresh QR ticket free of charge to avoid an argument', 'वाद टाळण्यासाठी नवीन QR तिकीट मोफत द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1219, 163, 4, 'Ask the passenger to buy a new ticket and claim a refund online', 'नवीन तिकीट घेऊन ऑनलाइन परतावा मागण्यास प्रवाशाला सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (164, 'D06-0002', NULL, 'D06', 'station_control', 3, 'Apply', 'numeric', 'During a shift a ticket office takes ₹18,450 in cash ticket sales and ₹6,200 in cash card top-ups, and pays ₹650 in refunds. The ₹5,000 float stays in the drawer. How much revenue cash (₹) must be deposited?', 'एका पाळीत तिकीट कार्यालयाला रोख तिकीट विक्रीतून ₹18,450 व रोख कार्ड टॉप-अपमधून ₹6,200 मिळतात आणि ₹650 परतावा दिला जातो. ₹5,000 ची सुरुवातीची रक्कम ड्रॉवरमध्येच राहते. किती महसूल रोख (₹) जमा करावी?', '18,450 + 6,200 − 650 = 24,000; the float is not revenue.', '18,450 + 6,200 − 650 = 24,000; the float is not revenue.', '18,450 + 6,200 − 650 = 24,000; सुरुवातीची रक्कम महसूल नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (165, 'D06-0003', NULL, 'D06', 'station_control', 2, 'Understand', 'truefalse', 'If the cash count at shift end is ₹50 short, the operator may make up the shortage personally and close the shift without reporting it.', 'पाळीच्या शेवटी रोख मोजणीत ₹50 कमी आढळल्यास, ऑपरेटर स्वतः ती रक्कम भरून न कळवता पाळी बंद करू शकतो.', 'Every shortage or excess must be recorded and reported; silent make-good hides errors and fraud.', 'Every shortage or excess must be recorded and reported; silent make-good hides errors and fraud.', 'प्रत्येक कमतरता किंवा जादा रक्कम नोंदवून कळवलीच पाहिजे; गुपचूप भरपाईमुळे चुका व गैरव्यवहार लपतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1220, 165, 1, 'True', 'बरोबर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1221, 165, 2, 'False', 'चूक', 1, '');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (166, 'D07-0001', NULL, 'D07', 'rolling_stock', 2, 'Understand', 'single', 'What is the main job of the TCMS on a metro train?', 'मेट्रो गाडीवरील TCMS चे मुख्य काम काय आहे?', 'The other options describe CBTC zone control, the auxiliary power supply and SCADA – systems often confused with TCMS.', 'The other options describe CBTC zone control, the auxiliary power supply and SCADA – systems often confused with TCMS.', 'इतर पर्याय CBTC झोन नियंत्रण, सहाय्यक वीजपुरवठा व SCADA यांचे वर्णन करतात – ज्या प्रणाली अनेकदा TCMS शी गोंधळल्या जातात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1222, 166, 1, 'Monitor train subsystems, show faults on the DMI and log events', 'गाडीच्या उप-प्रणालींवर लक्ष ठेवणे, DMI वर दोष दाखवणे व घटना नोंदवणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1223, 166, 2, 'Calculate the movement authority sent by the zone controller', 'झोन कंट्रोलरकडून येणारा हालचाल-अधिकार ठरवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1224, 166, 3, 'Supply auxiliary power to the lighting and air-conditioning', 'प्रकाश व वातानुकूलनाला सहाय्यक वीज पुरवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1225, 166, 4, 'Supervise the traction power supply of the line section', 'मार्ग-विभागाच्या ट्रॅक्शन वीजपुरवठ्यावर देखरेख ठेवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (167, 'D07-0002', NULL, 'D07', 'rolling_stock', 2, 'Remember', 'multi', 'Which braking systems are found on a typical metro train?', 'सामान्य मेट्रो गाडीवर कोणत्या ब्रेक प्रणाली असतात?', 'Metro trains blend regenerative electric braking with pneumatic friction brakes and have a spring-applied parking brake. There are no wayside or PSD brakes.', 'Metro trains blend regenerative electric braking with pneumatic friction brakes and have a spring-applied parking brake. There are no wayside or PSD brakes.', 'मेट्रो गाड्यांत पुनरुत्पादक विद्युत ब्रेक व वायवीय घर्षण ब्रेक एकत्र वापरतात, शिवाय स्प्रिंग-पार्किंग ब्रेक असतो. मार्गालगत किंवा PSD ब्रेक नसतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1226, 167, 1, 'Electric (regenerative) brake', 'विद्युत (रीजनरेटिव्ह) ब्रेक', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1227, 167, 2, 'Pneumatic friction brake', 'न्यूमॅटिक घर्षण ब्रेक', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1228, 167, 3, 'Spring-applied parking brake', 'स्प्रिंगने लागणारा पार्किंग ब्रेक', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1229, 167, 4, 'Wayside brake applied from SCADA', 'SCADA वरून लावला जाणारा मार्गालगतचा ब्रेक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1230, 167, 5, 'Brake applied by the platform screen doors', 'प्लॅटफॉर्म स्क्रीन दरवाजांनी लावला जाणारा ब्रेक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (168, 'D07-0003', NULL, 'D07', 'rolling_stock', 1, 'Remember', 'single', 'On Maha Metro trains, which component collects traction current from the line?', 'महा मेट्रोच्या गाड्यांवर मार्गावरून ट्रॅक्शन विद्युत प्रवाह कोणता भाग घेतो?', 'Overhead (OHE) supply is collected by the pantograph; collector shoes are used on third-rail systems.', 'Overhead (OHE) supply is collected by the pantograph; collector shoes are used on third-rail systems.', 'ओव्हरहेड (OHE) पुरवठा पॅन्टोग्राफद्वारे घेतला जातो; कलेक्टर शू तिसऱ्या-रूळ प्रणालीत वापरतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1231, 168, 1, 'Pantograph', 'पॅन्टोग्राफ', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1232, 168, 2, 'Collector shoe', 'कलेक्टर शू', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1233, 168, 3, 'Earth return brush', 'अर्थ रिटर्न ब्रश', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1234, 168, 4, 'Line breaker', 'लाइन ब्रेकर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (169, 'D07-0004', NULL, 'D07', 'rolling_stock', 3, 'Analyse', 'single', 'During train preparation, main reservoir pressure builds up slowly and the compressor keeps running. What is the most likely cause to check first?', 'गाडीच्या तयारीदरम्यान मुख्य जलाशयातील दाब हळूहळू वाढतो आणि कॉम्प्रेसर सतत चालू राहतो. आधी तपासायचे सर्वात संभाव्य कारण कोणते?', 'A compressor that runs on while pressure rises slowly most often points to an air leak. Check the pipework and couplings first.', 'A compressor that runs on while pressure rises slowly most often points to an air leak. Check the pipework and couplings first.', 'दाब हळू वाढत असताना कॉम्प्रेसर सतत चालणे बहुधा हवा-गळती दाखवते. आधी पाइपलाइन व जोडण्या तपासा.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1235, 169, 1, 'An air leak in the brake or main reservoir pipework', 'ब्रेक किंवा मुख्य जलाशयाच्या पाइपमध्ये हवा गळती', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1236, 169, 2, 'Low battery voltage during the train start-up', 'गाडी सुरू होताना बॅटरीचा कमी व्होल्टेज', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1237, 169, 3, 'An overloaded air-conditioning unit on one car', 'एका डब्यातील ओव्हरलोड झालेले वातानुकूलन यंत्र', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1238, 169, 4, 'A worn carbon strip on the pantograph', 'पॅन्टोग्राफवरील झिजलेली कार्बन पट्टी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (170, 'D08-0001', NULL, 'D08', 'signaling_telecom', 2, 'Understand', 'single', 'What is the main purpose of interlocking?', 'इंटरलॉकिंगचा मुख्य उद्देश काय आहे?', 'Braking curves belong to ATP, broken-rail detection to track circuits and scheduling to ATS.', 'Braking curves belong to ATP, broken-rail detection to track circuits and scheduling to ATS.', 'ब्रेकिंग वक्र ATP चे, तुटलेला रूळ शोधणे ट्रॅक सर्किटचे व नियोजन ATS चे काम आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1239, 170, 1, 'Preventing conflicting routes, points and signals', 'परस्परविरोधी मार्ग, पॉइंट्स व सिग्नल रोखणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1240, 170, 2, 'Calculating the safe braking curve for each train', 'प्रत्येक गाडीसाठी सुरक्षित ब्रेकिंग वक्र ठरवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1241, 170, 3, 'Detecting broken rails within the track sections', 'रूळ-विभागांतील तुटलेले रूळ शोधणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1242, 170, 4, 'Scheduling trains to the timetable automatically', 'वेळापत्रकानुसार गाड्यांचे आपोआप नियोजन करणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (171, 'D08-0002', NULL, 'D08', 'signaling_telecom', 3, 'Apply', 'single', 'After a power interruption, an axle-counter section shows ''occupied'' although no train is in it. What is generally required before normal working resumes?', 'वीज खंडित झाल्यानंतर, गाडी नसतानाही एक ॲक्सल-काउंटर विभाग ''व्यापलेला'' दाखवतो. सामान्य कामकाज सुरू होण्यापूर्वी सामान्यतः काय आवश्यक असते?', 'An axle counter that lost its count cannot be trusted. Confirm the section is clear by the laid-down method before resetting. Resetting blind can hide a real train.', 'An axle counter that lost its count cannot be trusted. Confirm the section is clear by the laid-down method before resetting. Resetting blind can hide a real train.', 'गणना हरवलेल्या ॲक्सल काउंटरवर विसंबू नये. रीसेटपूर्वी विहित पद्धतीने विभाग मोकळा असल्याची खात्री करा. अंधपणे रीसेट केल्यास खरी गाडी लपू शकते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1243, 171, 1, 'Confirm the section is clear as laid down, then reset by the procedure', 'नियमानुसार विभाग मोकळा असल्याची खात्री करा, मग कार्यपद्धतीनुसार रीसेट करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1244, 171, 2, 'Reset it at once from the SCR, as no train is shown in the section', 'विभागात गाडी दिसत नसल्याने SCR वरून लगेच रीसेट करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1245, 171, 3, 'Wait for the next train to pass, which will clear it on its own', 'पुढची गाडी जाऊ द्या, त्याने ते आपोआप मोकळे होईल', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1246, 171, 4, 'Replace the counting head, as the fault means it is damaged', 'काउंटिंग हेड बदला, कारण दोष म्हणजे ते खराब झाले आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (172, 'D08-0003', NULL, 'D08', 'signaling_telecom', 2, 'Apply', 'single', 'Your train stands at the signal shown. OCC tells you by radio to pass it. What must you do before moving?', 'दाखवलेल्या सिग्नलवर तुमची गाडी उभी आहे. OCC रेडिओवर तो ओलांडण्यास सांगते. हलवण्यापूर्वी तुम्ही काय करणे आवश्यक आहे?', 'Authority to pass a signal at danger must be repeated back to confirm it. The train then moves at restricted speed, ready to stop short of any obstruction.', 'Authority to pass a signal at danger must be repeated back to confirm it. The train then moves at restricted speed, ready to stop short of any obstruction.', 'धोक्याचा सिग्नल ओलांडण्याची परवानगी परत उच्चारून पक्की करावी. त्यानंतर कोणत्याही अडथळ्यापुढे थांबता येईल अशा प्रतिबंधित वेगाने जावे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1247, 172, 1, 'Repeat the authority back, then go at restricted speed', 'अधिकार पुन्हा उच्चारा, मग प्रतिबंधित वेगाने जा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1248, 172, 2, 'Move at normal speed, as OCC has already given permission', 'OCC ने परवानगी दिल्याने सामान्य वेगाने जा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1249, 172, 3, 'Ask the Station Controller to confirm the route is set', 'मार्ग सेट असल्याची स्टेशन कंट्रोलरकडून खात्री घ्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1250, 172, 4, 'Wait for the signal to clear, whatever OCC instructs', 'OCC काहीही सांगो, सिग्नल मोकळा होण्याची वाट पहा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (173, 'D08-0004', NULL, 'D08', 'signaling_telecom', 1, 'Remember', 'truefalse', 'CBTC relies on continuous two-way radio communication between the train and wayside equipment.', 'CBTC गाडी व मार्गालगतच्या उपकरणांमधील सतत द्विमार्गी रेडिओ संवादावर अवलंबून असते.', 'CBTC continuously exchanges train position and movement authority over radio between the train and the wayside.', 'CBTC continuously exchanges train position and movement authority over radio between the train and the wayside.', 'CBTC मध्ये गाडी व मार्गालगत उपकरणांत रेडिओद्वारे स्थान व गती-अधिकार सतत देवाणघेवाण होते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1251, 173, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1252, 173, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (174, 'D08-0005', NULL, 'D08', 'signaling_telecom', 1, 'Remember', 'single', 'Watch the clip. Which aspect does the signal show at the end?', 'क्लिप पहा. शेवटी सिग्नल कोणता संकेत दाखवतो?', 'The clip ends with the signal at red (stop).', 'The clip ends with the signal at red (stop).', 'क्लिपच्या शेवटी सिग्नल लाल (थांबा) दाखवतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1253, 174, 1, 'Red', 'लाल', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1254, 174, 2, 'Yellow', 'पिवळा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1255, 174, 3, 'Green', 'हिरवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1256, 174, 4, 'Flashing yellow', 'लुकलुकणारा पिवळा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (175, 'D09-0001', NULL, 'D09', 'signaling_telecom', 2, 'Understand', 'single', 'The OCC power controller opens a traction breaker remotely. Which system carries this command?', 'OCC पॉवर कंट्रोलर दूरस्थपणे ट्रॅक्शन ब्रेकर उघडतो. ही आज्ञा कोणती प्रणाली पोहोचवते?', 'SCADA carries remote control and indications for traction and E&M equipment.', 'SCADA carries remote control and indications for traction and E&M equipment.', 'ट्रॅक्शन व E&M उपकरणांचे दूरनियंत्रण व संकेत SCADA द्वारे होतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1257, 175, 1, 'SCADA', 'SCADA', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1258, 175, 2, 'Train radio', 'ट्रेन रेडिओ', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1259, 175, 3, 'PIDS', 'PIDS', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1260, 175, 4, 'Master clock', 'मास्टर क्लॉक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (176, 'D09-0002', NULL, 'D09', 'signaling_telecom', 2, 'Remember', 'match', 'Match each telecom system with its use.', 'प्रत्येक दूरसंचार प्रणालीची तिच्या उपयोगाशी जोडणी करा.', 'PIDS informs passengers, radio is for staff voice, CCTV is surveillance, and the master clock synchronises all systems'' time.', 'PIDS informs passengers, radio is for staff voice, CCTV is surveillance, and the master clock synchronises all systems'' time.', 'PIDS प्रवाशांना माहिती देते, रेडिओ कर्मचाऱ्यांच्या संवादासाठी, CCTV देखरेखीसाठी, आणि मास्टर क्लॉक सर्व प्रणालींची वेळ जुळवते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (177, 'D09-0003', NULL, 'D09', 'signaling_telecom', 3, 'Apply', 'single', 'Police ask for CCTV footage of a theft at your station. What should be done?', 'तुमच्या स्थानकावरील चोरीचे CCTV फुटेज पोलीस मागतात. काय करावे?', 'Footage is evidence: act on a written request, export a copy and log the chain of custody. Never hand over the recorder itself.', 'Footage is evidence: act on a written request, export a copy and log the chain of custody. Never hand over the recorder itself.', 'फुटेज हा पुरावा आहे: लेखी मागणीवर प्रत काढून द्या व हस्तांतरणाची नोंद ठेवा. रेकॉर्डरच कधीही देऊ नये.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1261, 177, 1, 'Take a written request, export the clip and log the handover', 'लेखी विनंती घ्या, क्लिप काढा व हस्तांतराची नोंद करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1262, 177, 2, 'Hand over the recorder''s hard disk so they get all of the footage', 'सर्व फुटेज मिळावे म्हणून रेकॉर्डरची हार्ड डिस्क द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1263, 177, 3, 'Play the footage for them in the SCR, but do not give any copy', 'SCR मध्ये फुटेज दाखवा, पण प्रत देऊ नका', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1264, 177, 4, 'Ask them to come back with a court order before doing anything', 'काहीही करण्यापूर्वी न्यायालयीन आदेश आणण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (178, 'D10-0001', NULL, 'D10', 'rolling_stock', 2, 'Understand', 'single', 'What is the main role of a Receiving Sub-Station (RSS)?', 'रिसीव्हिंग सब-स्टेशन (RSS) ची मुख्य भूमिका काय आहे?', 'The RSS receives high-voltage grid supply and steps it down to 25 kV for traction and to lower voltages for auxiliaries.', 'The RSS receives high-voltage grid supply and steps it down to 25 kV for traction and to lower voltages for auxiliaries.', 'RSS ग्रिडचा उच्च-दाब पुरवठा घेऊन ट्रॅक्शनसाठी 25 kV व सहायक भारांसाठी कमी दाबावर आणते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1265, 178, 1, 'Take grid supply and step it down for traction and auxiliaries', 'ग्रिड पुरवठा घेऊन ट्रॅक्शन व सहाय्यक भारासाठी कमी करणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1266, 178, 2, 'Convert AC to DC for a third-rail traction system', 'तिसऱ्या-रूळ ट्रॅक्शनसाठी AC चे DC मध्ये रूपांतर करणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1267, 178, 3, 'Store regenerated braking energy in station batteries', 'रीजनरेटिव्ह ब्रेकिंग ऊर्जा स्थानकांच्या बॅटरीत साठवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1268, 178, 4, 'Supply power to the signalling and telecom systems only', 'फक्त सिग्नलिंग व दूरसंचार प्रणालींना वीज पुरवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (179, 'D10-0002', NULL, 'D10', 'rolling_stock', 2, 'Understand', 'truefalse', 'The OHE must be treated as live until it has been isolated, tested dead and earthed under a valid permit.', 'वैध परवान्याअंतर्गत OHE वेगळी करून, मृत असल्याची चाचणी करून व अर्थिंग करेपर्यंत ती चालूच मानली पाहिजे.', 'Only isolation, a test for dead and earthing under a permit make OHE safe to touch. Until then it is treated as live.', 'Only isolation, a test for dead and earthing under a permit make OHE safe to touch. Until then it is treated as live.', 'परवान्याखाली विलगीकरण, विजविरहित चाचणी व अर्थिंग झाल्याशिवाय OHE सुरक्षित नाही; तोपर्यंत तो जिवंत मानावा.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1269, 179, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1270, 179, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (180, 'D10-0003', NULL, 'D10', 'rolling_stock', 3, 'Apply', 'single', 'Your team has a power block for OHE work. The TPC confirms the section is switched off. What must happen before anyone touches the OHE?', 'OHE कामासाठी तुमच्या टीमला पॉवर ब्लॉक मिळाला आहे. TPC विभाग बंद असल्याची खात्री देतो. कोणीही OHE ला स्पर्श करण्यापूर्वी काय झाले पाहिजे?', 'A SCADA indication or a waiting time is not proof. Test for absence of voltage on site and earth on both sides of the work.', 'A SCADA indication or a waiting time is not proof. Test for absence of voltage on site and earth on both sides of the work.', 'SCADA संकेत किंवा थांबणे हा पुरावा नाही. जागेवर विजेचा अभाव तपासा व कामाच्या दोन्ही बाजूंना अर्थिंग करा.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1271, 180, 1, 'Test for absence of voltage and apply earths on both sides', 'व्होल्टेज नसल्याची चाचणी करा व दोन्ही बाजूंना अर्थ लावा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1272, 180, 2, 'Wait five minutes so any residual charge drains away', 'उरलेला भार निघून जावा म्हणून पाच मिनिटे थांबा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1273, 180, 3, 'Apply one earth near the work site, then start the work', 'कामाच्या ठिकाणाजवळ एक अर्थ लावा, मग काम सुरू करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1274, 180, 4, 'Check that the SCADA screen shows the breaker as open', 'SCADA स्क्रीनवर ब्रेकर उघडा दिसतो याची खात्री करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (181, 'D11-0001', NULL, 'D11', 'rolling_stock', 2, 'Apply', 'single', 'A child''s shoe gets caught at the comb plate of a moving escalator. What should you do first?', 'चालू एस्केलेटरच्या कोम्ब प्लेटमध्ये मुलाचा बूट अडकतो. तुम्ही प्रथम काय कराल?', 'Stopping the escalator at once prevents injury. Pulling the foot or reversing while it is moving can make the injury worse.', 'Stopping the escalator at once prevents injury. Pulling the foot or reversing while it is moving can make the injury worse.', 'एस्केलेटर लगेच थांबवल्याने इजा टळते. चालू असताना पाय ओढणे किंवा उलट फिरवणे इजा वाढवू शकते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1275, 181, 1, 'Press the escalator emergency stop at once', 'एस्केलेटरचे आपत्कालीन थांबा बटण लगेच दाबा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1276, 181, 2, 'Help the parent pull the child''s foot free', 'पालकांना मुलाचा पाय ओढून सोडवण्यास मदत करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1277, 181, 3, 'Reverse the escalator so the shoe is released', 'बूट सुटावा म्हणून एस्केलेटरची दिशा उलटा करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1278, 181, 4, 'Switch it off at the panel in the E&M room', 'E&M कक्षातील पॅनेलवरून ते बंद करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (182, 'D11-0002', NULL, 'D11', 'rolling_stock', 3, 'Apply', 'sequence', 'Put the steps to rescue passengers from a stalled lift in the correct order.', 'बंद पडलेल्या लिफ्टमधून प्रवाशांची सुटका करण्याचे टप्पे क्रमाने लावा.', 'Reassure the passengers, isolate the power, confirm where the car is, bring it to a landing, and only then open the doors with the key.', 'Reassure the passengers, isolate the power, confirm where the car is, bring it to a landing, and only then open the doors with the key.', 'प्रवाशांना धीर द्या, वीज विलग करा, केबिनचे स्थान निश्चित करा, मजल्यापर्यंत आणा आणि मगच चावीने दरवाजे उघडा.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (183, 'D11-0003', NULL, 'D11', 'rolling_stock', 2, 'Remember', 'match', 'Match each E&M system with its function.', 'प्रत्येक E&M प्रणालीची कार्याशी जोडणी करा.', 'TVS controls tunnel air and smoke, BMS monitors building services, FDAS detects fire and raises the alarm, and UPS backs up critical loads.', 'TVS controls tunnel air and smoke, BMS monitors building services, FDAS detects fire and raises the alarm, and UPS backs up critical loads.', 'TVS बोगद्यातील हवा व धूर नियंत्रित करते, BMS इमारत सेवांवर देखरेख करते, FDAS आग शोधून अलार्म देते, UPS महत्त्वाच्या भारांना बॅकअप देते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (184, 'D12-0001', NULL, 'D12', 'rolling_stock', 3, 'Apply', 'single', 'During a track patrol you find a crack at a rail weld on the running line. What should you do first?', 'रूळ-गस्तीदरम्यान धावत्या मार्गावर रूळाच्या वेल्डला भेग आढळते. तुम्ही प्रथम काय कराल?', 'A weld crack can lead to a rail fracture under the next train. Protecting traffic through OCC comes before repair or reporting.', 'A weld crack can lead to a rail fracture under the next train. Protecting traffic through OCC comes before repair or reporting.', 'वेल्डमधील तडा पुढील गाडीखाली रेल तुटण्यास कारण ठरू शकतो. दुरुस्ती किंवा अहवालापेक्षा OCC मार्फत वाहतूक सुरक्षित करणे आधी.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1279, 184, 1, 'Inform OCC at once so trains are stopped or restricted', 'गाड्या थांबवाव्या किंवा मर्यादित कराव्या म्हणून लगेच OCC ला कळवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1280, 184, 2, 'Mark it with paint and include it in the end-of-shift report', 'रंगाने खूण करा व पाळीअखेरच्या अहवालात नोंदवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1281, 184, 3, 'Fit joggled fishplates yourself before the first train', 'पहिल्या गाडीपूर्वी स्वतः जॉगल्ड फिशप्लेट लावा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1282, 184, 4, 'Finish the patrol first and then report all defects together', 'आधी गस्त पूर्ण करा व मग सर्व दोष एकत्र कळवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (185, 'D12-0002', NULL, 'D12', 'rolling_stock', 2, 'Understand', 'truefalse', 'Long welded rails need monitoring of rail temperature because of thermal stresses.', 'उष्णतेमुळे होणाऱ्या ताणामुळे लाँग वेल्डेड रेलच्या तापमानावर लक्ष ठेवावे लागते.', 'Long welded rails cannot expand freely, so high temperatures can cause buckling and low temperatures can cause fractures. Rail temperature is therefore monitored.', 'Long welded rails cannot expand freely, so high temperatures can cause buckling and low temperatures can cause fractures. Rail temperature is therefore monitored.', 'लांब वेल्डेड रेल मुक्तपणे प्रसरण पावू शकत नाहीत; जास्त तापमानात वाकणे व कमी तापमानात तुटणे संभवते. म्हणून रेल-तापमानावर लक्ष ठेवतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1283, 185, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1284, 185, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (186, 'D12-0003', NULL, 'D12', 'rolling_stock', 2, 'Remember', 'single', 'Ultrasonic flaw detection (USFD) of rails mainly finds:', 'रुळांच्या अल्ट्रासोनिक दोष-शोध (USFD) चाचणीत मुख्यतः काय आढळते?', 'USFD sends ultrasound into the rail to find internal flaws that cannot be seen. Gauge, wear and ballast are checked by other methods.', 'USFD sends ultrasound into the rail to find internal flaws that cannot be seen. Gauge, wear and ballast are checked by other methods.', 'USFD रेलमध्ये अल्ट्रासाउंड पाठवून न दिसणारे आतील दोष शोधते. गेज, झीज व खडी इतर पद्धतींनी तपासतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1285, 186, 1, 'Internal flaws and cracks', 'आतील दोष व भेगा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1286, 186, 2, 'Gauge widening', 'गेज रुंदावणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1287, 186, 3, 'Railhead wear profile', 'रेलहेड झीज प्रोफाइल', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1288, 186, 4, 'Ballast fouling', 'खडी दूषित होणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (187, 'D12-0004', NULL, 'D12', 'rolling_stock', 1, 'Remember', 'single', 'What is the track gauge of Maha Metro''s standard-gauge lines?', 'महा मेट्रोच्या स्टँडर्ड-गेज मार्गांचे गेज किती आहे?', 'Standard gauge is 1435 mm; 1676 mm is Indian broad gauge and 1000 mm is metre gauge.', 'Standard gauge is 1435 mm; 1676 mm is Indian broad gauge and 1000 mm is metre gauge.', 'स्टँडर्ड गेज 1435 मिमी आहे; 1676 मिमी भारतीय ब्रॉड गेज व 1000 मिमी मीटर गेज आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1289, 187, 1, '1435 mm', '1435 मिमी', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1290, 187, 2, '1676 mm', '1676 मिमी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1291, 187, 3, '1000 mm', '1000 मिमी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1292, 187, 4, '1520 mm', '1520 मिमी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (188, 'D13-0001', NULL, 'D13', 'workplace_ethics', 3, 'Apply', 'sequence', 'Arrange the steps before starting work on isolated electrical equipment.', 'वेगळ्या केलेल्या विद्युत उपकरणावर काम सुरू करण्यापूर्वीचे टप्पे क्रमाने लावा.', 'Work authority first, then isolate and lock, prove dead, then earth. Earthing before proving dead is unsafe.', 'Work authority first, then isolate and lock, prove dead, then earth. Earthing before proving dead is unsafe.', 'आधी कार्य-अधिकार, मग वेगळे करून कुलूप, मृत असल्याची खात्री, मग अर्थिंग. खात्रीपूर्वी अर्थिंग असुरक्षित आहे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (189, 'D13-0002', NULL, 'D13', 'workplace_ethics', 2, 'Understand', 'single', 'Why does each worker put a personal lock on the isolation point (lock-out/tag-out)?', 'प्रत्येक कामगार विलगीकरण बिंदूवर वैयक्तिक कुलूप (लॉक-आउट/टॅग-आउट) का लावतो?', 'Each worker''s own lock means the supply cannot be restored until every lock is removed, which protects every person working.', 'Each worker''s own lock means the supply cannot be restored until every lock is removed, which protects every person working.', 'प्रत्येक कामगाराचे स्वतःचे कुलूप असल्याने सर्व कुलपे काढल्याशिवाय पुरवठा सुरू करता येत नाही – प्रत्येकाचे संरक्षण होते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1293, 189, 1, 'So the supply cannot be restored while anyone is still working', 'कोणी काम करत असताना पुरवठा पुन्हा सुरू होऊ नये म्हणून', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1294, 189, 2, 'So the supervisor can see who attended the job that day', 'त्या दिवशी कामावर कोण होते ते पर्यवेक्षकाला कळावे म्हणून', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1295, 189, 3, 'So the equipment cannot be stolen during the shutdown', 'बंद काळात उपकरण चोरीला जाऊ नये म्हणून', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1296, 189, 4, 'So the permit can be closed without the issuer present', 'जारीकर्ता नसतानाही परवाना बंद करता यावा म्हणून', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (190, 'D13-0003', NULL, 'D13', 'workplace_ethics', 2, 'Understand', 'truefalse', 'A permit-to-work may be cancelled only after all staff and materials are clear and the earths are removed.', 'सर्व कर्मचारी व साहित्य बाजूला झाल्यावर व अर्थ काढल्यावरच कार्य-परवाना रद्द करता येतो.', 'A permit is cancelled only when people, materials and temporary earths are clear. Otherwise the supply could be restored onto a person or an earth.', 'A permit is cancelled only when people, materials and temporary earths are clear. Otherwise the supply could be restored onto a person or an earth.', 'माणसे, साहित्य व तात्पुरती अर्थिंग हटवल्यानंतरच परवाना रद्द करतात; नाहीतर पुरवठा एखाद्या व्यक्तीवर किंवा अर्थवर येऊ शकतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1297, 190, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1298, 190, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (191, 'D13-0004', NULL, 'D13', 'workplace_ethics', 3, 'Apply', 'sjt', 'Your supervisor asks you to quickly replace a fuse in a live LT panel to avoid delaying service. No permit has been issued. What do you do?', 'सेवा उशिरा होऊ नये म्हणून पर्यवेक्षक तुम्हाला चालू LT पॅनेलमधील फ्यूज पटकन बदलण्यास सांगतात. परवाना दिलेला नाही. तुम्ही काय कराल?', 'Live LT work without isolation and a permit is not allowed. PPE does not replace isolation. Explaining and arranging it keeps both safety and service.', 'Live LT work without isolation and a permit is not allowed. PPE does not replace isolation. Explaining and arranging it keeps both safety and service.', 'विलगीकरण व परवान्याशिवाय जिवंत LT काम निषिद्ध आहे; PPE विलगीकरणाचा पर्याय नाही. कारण सांगून व्यवस्था केल्याने सुरक्षा व सेवा दोन्ही राखली जातात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1299, 191, 1, 'Explain that isolation and a permit are needed, and arrange them', 'विलगीकरण व परवाना आवश्यक असल्याचे सांगा व ते मिळवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1300, 191, 2, 'Do it wearing insulated gloves and using insulated tools', 'इन्सुलेटेड हातमोजे व साधने वापरून ते करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1301, 191, 3, 'Do it, but ask a colleague to stand by the panel', 'करा, पण एका सहकाऱ्याला पॅनेलजवळ उभे राहण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1302, 191, 4, 'Refuse and leave the site until a permit is issued', 'नकार द्या व परवाना मिळेपर्यंत जागा सोडा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (192, 'D14-0001', NULL, 'D14', 'workplace_ethics', 2, 'Apply', 'numeric', 'A fleet ran 12,50,000 car-km last quarter with 50 service-affecting failures. What is the MDBF (km)?', 'मागील तिमाहीत ताफ्याने 12,50,000 कार-किमी धाव घेतली आणि सेवेवर परिणाम करणारे 50 बिघाड झाले. MDBF (किमी) किती?', 'MDBF = distance ÷ failures = 12,50,000 ÷ 50 = 25,000 km.', 'MDBF = distance ÷ failures = 12,50,000 ÷ 50 = 25,000 km.', 'MDBF = अंतर ÷ बिघाड = 12,50,000 ÷ 50 = 25,000 किमी.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (193, 'D14-0002', NULL, 'D14', 'workplace_ethics', 2, 'Apply', 'numeric', 'An equipment type had 5 failures last month with a total repair time of 10 hours. What is the MTTR in hours?', 'एका उपकरण प्रकारात मागील महिन्यात 5 बिघाड झाले व एकूण दुरुस्ती वेळ 10 तास होता. MTTR किती तास?', 'MTTR = total repair time ÷ number of repairs = 10 ÷ 5 = 2 hours.', 'MTTR = total repair time ÷ number of repairs = 10 ÷ 5 = 2 hours.', 'MTTR = एकूण दुरुस्ती वेळ ÷ दुरुस्त्यांची संख्या = 10 ÷ 5 = 2 तास.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (194, 'D14-0003', NULL, 'D14', 'workplace_ethics', 4, 'Analyse', 'single', 'Which data best shows that a preventive maintenance interval is too long?', 'प्रतिबंधात्मक देखभालीचा कालावधी खूप लांब आहे हे कोणती माहिती सर्वात चांगली दाखवते?', 'Failures bunching just before PM is due show that parts are wearing out before the interval ends.', 'Failures bunching just before PM is due show that parts are wearing out before the interval ends.', 'PM देय होण्याच्या आधी दोष एकवटणे म्हणजे भाग अंतराल संपण्यापूर्वीच झिजत आहेत.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1303, 194, 1, 'Failures clustering just before each PM due date', 'प्रत्येक PM देय तारखेच्या आधी बिघाड एकवटणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1304, 194, 2, 'Total maintenance hours booked in the last quarter', 'मागील तिमाहीत नोंदवलेले एकूण देखभाल तास', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1305, 194, 3, 'Number of spare parts issued from stores', 'भांडारातून दिलेल्या सुट्या भागांची संख्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1306, 194, 4, 'Overtime hours worked by the maintenance team', 'देखभाल टीमने केलेले जादा तास', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (195, 'D15-0001', NULL, 'D15', 'workplace_ethics', 3, 'Understand', 'single', 'What is an interface management plan used for in a metro project?', 'मेट्रो प्रकल्पात इंटरफेस व्यवस्थापन योजना कशासाठी वापरतात?', 'Interface management fixes responsibility where systems or contracts meet (for example, civil-E&M or track-signalling), which is a major source of delays.', 'Interface management fixes responsibility where systems or contracts meet (for example, civil-E&M or track-signalling), which is a major source of delays.', 'प्रणाली किंवा कंत्राटे जिथे जुळतात (उदा. सिव्हिल-E&M, ट्रॅक-सिग्नलिंग) तिथली जबाबदारी इंटरफेस व्यवस्थापन ठरवते – विलंबाचे मोठे कारण.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1307, 195, 1, 'Defining who delivers what where two systems or contracts meet', 'दोन प्रणाली किंवा करार जिथे भेटतात तिथे कोण काय देणार ते ठरवणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1308, 195, 2, 'Recording design changes after the contract is awarded', 'करार दिल्यानंतरचे आराखडा बदल नोंदवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1309, 195, 3, 'Planning the order in which stations are opened', 'स्थानके कोणत्या क्रमाने सुरू होतील याचे नियोजन', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1310, 195, 4, 'Listing the user-interface screens of each system', 'प्रत्येक प्रणालीच्या वापरकर्ता-स्क्रीनची यादी करणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (196, 'D15-0002', NULL, 'D15', 'workplace_ethics', 2, 'Remember', 'single', 'Which Indian Standard is the code of practice for plain and reinforced concrete?', 'साध्या व प्रबलित काँक्रीटसाठी कोणते भारतीय मानक आहे?', 'IS 456 covers plain and reinforced concrete, IS 800 covers steel, IS 1893 covers earthquake design and IS 875 covers design loads.', 'IS 456 covers plain and reinforced concrete, IS 800 covers steel, IS 1893 covers earthquake design and IS 875 covers design loads.', 'IS 456 साधे व प्रबलित काँक्रीट, IS 800 पोलाद, IS 1893 भूकंप-रचना, IS 875 रचना-भार.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1311, 196, 1, 'IS 456', 'IS 456', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1312, 196, 2, 'IS 800', 'IS 800', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1313, 196, 3, 'IS 1893', 'IS 1893', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1314, 196, 4, 'IS 875', 'IS 875', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (197, 'D15-0003', NULL, 'D15', 'workplace_ethics', 3, 'Analyse', 'single', 'The civil contractor proposes to reduce an escalator well opening by 150 mm to suit a beam. Before approval, who must review the change?', 'बीमला जुळवून घेण्यासाठी स्थापत्य कंत्राटदार एस्केलेटर विहिरीचे उघडे 150 मिमीने कमी करण्याचा प्रस्ताव देतो. मंजुरीपूर्वी हा बदल कोणी तपासला पाहिजे?', 'A civil change at an E&M interface can make the escalator impossible to install. The interfacing designer must review it.', 'A civil change at an E&M interface can make the escalator impossible to install. The interfacing designer must review it.', 'E&M इंटरफेसवरील सिव्हिल बदलामुळे एस्केलेटर बसवणे अशक्य होऊ शकते; संबंधित डिझायनरने तो तपासलाच पाहिजे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1315, 197, 1, 'The E&M (escalator) designer through the interface process', 'इंटरफेस प्रक्रियेद्वारे E&M (एस्केलेटर) आराखडाकार', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1316, 197, 2, 'Only the structural designer, as it is a civil change', 'फक्त संरचना आराखडाकार, कारण हा स्थापत्य बदल आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1317, 197, 3, 'Only the architect, as it affects the station layout', 'फक्त वास्तुविशारद, कारण स्थानकाच्या मांडणीवर परिणाम होतो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1318, 197, 4, 'No one, as 150 mm is within construction tolerance', 'कोणीही नाही, कारण 150 मिमी बांधकाम सहनशीलतेत आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (198, 'D16-0001', NULL, 'D16', 'workplace_ethics', 3, 'Apply', 'numeric', 'Earned value is ₹80 lakh and planned value is ₹100 lakh. What is the Schedule Performance Index (SPI)?', 'अर्जित मूल्य ₹80 लाख व नियोजित मूल्य ₹100 लाख आहे. शेड्यूल परफॉर्मन्स इंडेक्स (SPI) किती?', 'SPI = EV ÷ PV = 80 ÷ 100 = 0.8 (behind schedule).', 'SPI = EV ÷ PV = 80 ÷ 100 = 0.8 (behind schedule).', 'SPI = EV ÷ PV = 80 ÷ 100 = 0.8 (वेळापत्रकापेक्षा मागे).', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (199, 'D16-0002', NULL, 'D16', 'workplace_ethics', 2, 'Understand', 'single', 'What does the critical path of a project schedule show?', 'प्रकल्प वेळापत्रकाचा क्रिटिकल पाथ काय दाखवतो?', 'The critical path is the longest chain of dependent activities. It has zero float and sets the shortest possible project duration.', 'The critical path is the longest chain of dependent activities. It has zero float and sets the shortest possible project duration.', 'क्रिटिकल पाथ ही परस्परावलंबी कामांची सर्वात लांब साखळी आहे; त्यात फ्लोट शून्य असतो व तीच प्रकल्पाचा किमान कालावधी ठरवते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1319, 199, 1, 'The chain of activities that sets the shortest duration', 'किमान कालावधी ठरवणारी कामांची साखळी', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1320, 199, 2, 'The activities that carry the highest cost in the budget', 'अर्थसंकल्पातील सर्वाधिक खर्चाची कामे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1321, 199, 3, 'The activities with the greatest safety risk', 'सर्वाधिक सुरक्षा-जोखमीची कामे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1322, 199, 4, 'The activities with the most float available', 'सर्वाधिक फ्लोट उपलब्ध असलेली कामे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (200, 'D16-0003', NULL, 'D16', 'workplace_ethics', 3, 'Apply', 'single', 'An activity with 10 days of total float is delayed by 6 days. Nothing else changes. What happens to the project finish date?', '10 दिवसांचा एकूण फ्लोट असलेले एक काम 6 दिवस उशिरा होते. बाकी काहीही बदलत नाही. प्रकल्प पूर्ण होण्याच्या तारखेचे काय होते?', 'The delay (6 days) is within the float (10 days), so the finish date holds; 4 days of float remain.', 'The delay (6 days) is within the float (10 days), so the finish date holds; 4 days of float remain.', 'विलंब (6 दिवस) फ्लोटमध्ये (10 दिवस) बसतो, त्यामुळे पूर्णत्वाची तारीख कायम राहते; 4 दिवसांचा फ्लोट उरतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1323, 200, 1, 'It does not change', 'ती बदलत नाही', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1324, 200, 2, 'It moves by 6 days', 'ती 6 दिवसांनी पुढे जाते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1325, 200, 3, 'It moves by 4 days', 'ती 4 दिवसांनी पुढे जाते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1326, 200, 4, 'It moves by 16 days', 'ती 16 दिवसांनी पुढे जाते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (201, 'D17-0001', NULL, 'D17', 'workplace_ethics', 3, 'Apply', 'single', '28-day cube results for a pier pour are below the specified strength. What is the right first step?', 'एका पियर ओतकामाचे 28 दिवसांचे क्यूब निकाल निर्धारित ताकदीपेक्षा कमी आहेत. योग्य पहिला टप्पा कोणता?', 'A non-conformance must be recorded and the dependent work held until investigation (for example, cores or load tests) decides the outcome.', 'A non-conformance must be recorded and the dependent work held until investigation (for example, cores or load tests) decides the outcome.', 'निकष न पाळल्याची NCR नोंद करावी व तपासणी (उदा. कोअर, भार चाचणी) निर्णय देईपर्यंत संबंधित काम थांबवावे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1327, 201, 1, 'Raise an NCR and hold related work while it is investigated', 'NCR काढा व तपास होईपर्यंत संबंधित काम थांबवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1328, 201, 2, 'Accept it, as concrete keeps gaining strength after 28 days', 'स्वीकारा, कारण 28 दिवसांनंतरही काँक्रीटची ताकद वाढते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1329, 201, 3, 'Cast fresh cubes from the next pour and use those results', 'पुढील ओतकामातून नवे क्यूब घ्या व ते निकाल वापरा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1330, 201, 4, 'Break out the pier and recast it straight away', 'पियर लगेच तोडून पुन्हा ओता', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (202, 'D17-0002', NULL, 'D17', 'workplace_ethics', 2, 'Understand', 'truefalse', 'Work must not proceed beyond a ''hold point'' in the inspection and test plan until it is formally released.', 'तपासणी व चाचणी योजनेतील ''होल्ड पॉइंट'' औपचारिकरीत्या मोकळा होईपर्यंत काम पुढे नेऊ नये.', 'A hold point needs formal release by the inspecting authority before work proceeds; this is what makes it different from a witness point.', 'A hold point needs formal release by the inspecting authority before work proceeds; this is what makes it different from a witness point.', 'होल्ड पॉइंटला पुढे जाण्यापूर्वी तपासणी अधिकाऱ्याची औपचारिक मंजुरी लागते; विटनेस पॉइंटपेक्षा हाच फरक.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1331, 202, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1332, 202, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (203, 'D17-0003', NULL, 'D17', 'workplace_ethics', 1, 'Remember', 'single', 'Concrete cube strength for acceptance is normally checked at:', 'स्वीकृतीसाठी काँक्रीट क्यूबची ताकद सामान्यतः केव्हा तपासतात?', 'Characteristic compressive strength is specified at 28 days. Earlier results only show the trend.', 'Characteristic compressive strength is specified at 28 days. Earlier results only show the trend.', 'वैशिष्ट्यपूर्ण संपीडन ताकद 28 दिवसांवर निर्दिष्ट असते; आधीचे निकाल फक्त कल दाखवतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1333, 203, 1, '28 days', '28 दिवस', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1334, 203, 2, '7 days', '7 दिवस', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1335, 203, 3, '3 days', '3 दिवस', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1336, 203, 4, '56 days', '56 दिवस', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (204, 'D18-0001', NULL, 'D18', 'workplace_ethics', 3, 'Understand', 'sequence', 'Arrange the hierarchy of controls from most to least effective.', 'नियंत्रणांची श्रेणी सर्वाधिक ते सर्वात कमी परिणामकारक अशी लावा.', 'Removing the hazard is the most effective control. PPE is the last line of defence because it depends on people using it correctly.', 'Removing the hazard is the most effective control. PPE is the last line of defence because it depends on people using it correctly.', 'धोका काढून टाकणे सर्वात प्रभावी; PPE शेवटचा उपाय, कारण तो योग्य वापरावर अवलंबून असतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (205, 'D18-0002', NULL, 'D18', 'workplace_ethics', 3, 'Apply', 'single', 'Which control most reduces the risk of a passenger falling from the platform onto the track?', 'प्रवासी प्लॅटफॉर्मवरून रुळावर पडण्याची जोखीम कोणते नियंत्रण सर्वाधिक कमी करते?', 'A physical barrier (engineering control) works without relying on people''s behaviour; markings, announcements and staff are administrative controls.', 'A physical barrier (engineering control) works without relying on people''s behaviour; markings, announcements and staff are administrative controls.', 'भौतिक अडथळा (अभियांत्रिकी नियंत्रण) लोकांच्या वर्तनावर अवलंबून न राहता काम करतो; रेषा, उद्घोषणा व कर्मचारी ही प्रशासकीय नियंत्रणे आहेत.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1337, 205, 1, 'Platform screen doors', 'प्लॅटफॉर्म स्क्रीन दरवाजे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1338, 205, 2, 'A yellow safety line', 'पिवळी सुरक्षा रेषा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1339, 205, 3, 'Frequent PA reminders', 'वारंवार PA सूचना', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1340, 205, 4, 'Extra platform staff', 'जादा प्लॅटफॉर्म कर्मचारी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (206, 'D18-0003', NULL, 'D18', 'workplace_ethics', 2, 'Remember', 'single', 'What is a hazard log used for?', 'हॅझर्ड लॉग कशासाठी वापरतात?', 'A hazard log records each hazard, its risk and its controls, and tracks them until closure.', 'A hazard log records each hazard, its risk and its controls, and tracks them until closure.', 'धोका-नोंदवहीत प्रत्येक धोका, त्याची जोखीम व नियंत्रणे नोंदवून ते बंद होईपर्यंत पाठपुरावा केला जातो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1341, 206, 1, 'Tracking each hazard and its controls until closure', 'प्रत्येक धोका व त्याची नियंत्रणे पूर्ण होईपर्यंत मागोवा घेणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1342, 206, 2, 'Recording accidents after they have happened', 'अपघात घडल्यानंतर त्यांची नोंद करणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1343, 206, 3, 'Listing safety equipment issued to each staff member', 'प्रत्येक कर्मचाऱ्याला दिलेल्या सुरक्षा साधनांची यादी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1344, 206, 4, 'Scheduling safety audits for the coming year', 'पुढील वर्षाच्या सुरक्षा लेखापरीक्षांचे नियोजन', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (207, 'D19-0001', NULL, 'D19', 'workplace_ethics', 3, 'Apply', 'single', 'March electricity charges of ₹4.2 lakh are billed by the supplier in April. In which financial year are they recorded?', 'मार्चचे ₹4.2 लाख वीज शुल्क पुरवठादार एप्रिलमध्ये बिल करतो. ते कोणत्या आर्थिक वर्षात नोंदवले जाते?', 'Under accrual accounting, an expense belongs to the period in which it was incurred, so the March charge is accrued in the year ending March.', 'Under accrual accounting, an expense belongs to the period in which it was incurred, so the March charge is accrued in the year ending March.', 'उपार्जन लेखांकनात खर्च ज्या काळात झाला त्या काळाचा असतो; म्हणून मार्चचा खर्च मार्चअखेरच्या वर्षात उपार्जित करतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1345, 207, 1, 'The year ending in March, as an accrued expense', 'मार्चमध्ये संपणाऱ्या वर्षात, उपार्जित खर्च म्हणून', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1346, 207, 2, 'The new year, when the bill is received in April', 'नव्या वर्षात, एप्रिलमध्ये बिल मिळाल्यावर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1347, 207, 3, 'Whichever year the payment is actually made in', 'प्रत्यक्ष देयक ज्या वर्षात होईल त्या वर्षात', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1348, 207, 4, 'Half in each year, as it spans the year-end', 'वर्षअखेर ओलांडते म्हणून दोन्ही वर्षांत अर्धे-अर्धे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (208, 'D19-0002', NULL, 'D19', 'workplace_ethics', 3, 'Apply', 'numeric', 'An asset costs ₹10,00,000, has a residual value of ₹1,00,000 and a useful life of 9 years. What is the annual straight-line depreciation (₹)?', 'एका मालमत्तेची किंमत ₹10,00,000, अवशिष्ट मूल्य ₹1,00,000 व उपयुक्त आयुष्य 9 वर्षे आहे. वार्षिक सरळ-रेषा घसारा किती (₹)?', '(10,00,000 − 1,00,000) ÷ 9 = 1,00,000', '(10,00,000 − 1,00,000) ÷ 9 = 1,00,000', '(10,00,000 − 1,00,000) ÷ 9 = 1,00,000', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (209, 'D19-0003', NULL, 'D19', 'workplace_ethics', 2, 'Understand', 'truefalse', 'An insurance premium paid in advance for next year is shown as an asset in this year''s balance sheet.', 'पुढील वर्षासाठी आगाऊ भरलेला विमा हप्ता या वर्षाच्या ताळेबंदात मालमत्ता म्हणून दाखवला जातो.', 'A prepaid expense gives a benefit in a future period, so it is shown as a current asset.', 'A prepaid expense gives a benefit in a future period, so it is shown as a current asset.', 'आगाऊ भरलेला खर्च पुढील काळात लाभ देतो, म्हणून तो चालू मालमत्ता म्हणून दाखवतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1349, 209, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1350, 209, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (210, 'D20-0001', NULL, 'D20', 'workplace_ethics', 3, 'Apply', 'numeric', 'A head has a BE of ₹50 crore. Spending from April to December is ₹30 crore and ₹12 crore is firmly expected from January to March. What RE (₹ crore) should be proposed?', 'एका शीर्षाचा BE ₹50 कोटी आहे. एप्रिल ते डिसेंबर खर्च ₹30 कोटी असून जानेवारी ते मार्चमध्ये ₹12 कोटी खर्च निश्चित अपेक्षित आहे. किती RE (₹ कोटी) प्रस्तावित करावे?', 'RE reflects realistic spending for the whole year: 30 + 12 = 42.', 'RE reflects realistic spending for the whole year: 30 + 12 = 42.', 'RE संपूर्ण वर्षाचा वास्तववादी खर्च दाखवते: 30 + 12 = 42.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (211, 'D20-0002', NULL, 'D20', 'workplace_ethics', 2, 'Understand', 'single', 'What is the difference between BE and RE?', 'BE व RE मध्ये काय फरक आहे?', 'The Budget Estimate (BE) is approved before the year. The Revised Estimate (RE) updates it mid-year based on actual progress.', 'The Budget Estimate (BE) is approved before the year. The Revised Estimate (RE) updates it mid-year based on actual progress.', 'अर्थसंकल्पीय अंदाज (BE) वर्षापूर्वी मंजूर होतो; सुधारित अंदाज (RE) वर्षाच्या मध्यात प्रत्यक्ष प्रगतीनुसार तो अद्ययावत करतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1351, 211, 1, 'BE is set before the year; RE revises it during the year', 'BE वर्षापूर्वी ठरते; RE वर्षादरम्यान त्यात सुधारणा करते', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1352, 211, 2, 'BE covers capital spending; RE covers revenue spending', 'BE भांडवली खर्चासाठी; RE महसुली खर्चासाठी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1353, 211, 3, 'BE is the department''s estimate; RE is Finance''s estimate', 'BE विभागाचा अंदाज; RE वित्त विभागाचा अंदाज', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1354, 211, 4, 'BE is the first half-year; RE is the second half-year', 'BE पहिले सहामाही; RE दुसरे सहामाही', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (212, 'D20-0003', NULL, 'D20', 'workplace_ethics', 2, 'Understand', 'single', 'When must a proposal be sent to Finance for concurrence?', 'प्रस्ताव वित्तीय सहमतीसाठी केव्हा पाठवला पाहिजे?', 'Finance concurrence is a pre-check, so it must come before the competent authority sanctions the proposal.', 'Finance concurrence is a pre-check, so it must come before the competent authority sanctions the proposal.', 'वित्त सहमती ही पूर्वतपासणी आहे; सक्षम प्राधिकाऱ्याच्या मंजुरीआधीच ती घ्यावी.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1355, 212, 1, 'Before the competent authority approves it', 'सक्षम प्राधिकारी मंजूर करण्यापूर्वी', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1356, 212, 2, 'After approval, before the work order is issued', 'मंजुरीनंतर, कार्यादेश देण्यापूर्वी', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1357, 212, 3, 'Only when the amount exceeds the budget provision', 'फक्त रक्कम अर्थसंकल्पीय तरतुदीपेक्षा जास्त असल्यास', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1358, 212, 4, 'When the first bill is received for payment', 'पहिले बिल देयकासाठी आल्यावर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (213, 'D21-0001', NULL, 'D21', 'workplace_ethics', 3, 'Apply', 'numeric', 'An intra-state service invoice is ₹50,000 before tax and GST is 18%. What is the CGST amount (₹)?', 'राज्यांतर्गत सेवा बीजक करपूर्व ₹50,000 आहे व GST 18% आहे. CGST रक्कम किती (₹)?', 'Intra-state supply: CGST 9% + SGST 9%. 9% of 50,000 = 4,500.', 'Intra-state supply: CGST 9% + SGST 9%. 9% of 50,000 = 4,500.', 'राज्यांतर्गत पुरवठा: CGST 9% + SGST 9%. 50,000 चे 9% = 4,500.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (214, 'D21-0002', NULL, 'D21', 'workplace_ethics', 2, 'Apply', 'numeric', 'A works contractor (a company) submits a bill of ₹10,00,000 excluding GST. TDS under Section 194C is 2%. How much TDS (₹) is deducted?', 'एक कंत्राटदार (कंपनी) GST वगळून ₹10,00,000 चे बिल सादर करतो. कलम 194C अंतर्गत TDS 2% आहे. किती TDS (₹) कापला जातो?', 'Under Section 194C, TDS for a company contractor is 2% of the amount excluding GST: 2% × ₹10,00,000 = ₹20,000.', 'Under Section 194C, TDS for a company contractor is 2% of the amount excluding GST: 2% × ₹10,00,000 = ₹20,000.', 'कलम 194C नुसार कंपनी कंत्राटदारासाठी TDS = GST वगळून रकमेच्या 2%: 2% × ₹10,00,000 = ₹20,000.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (215, 'D21-0003', NULL, 'D21', 'workplace_ethics', 2, 'Understand', 'truefalse', 'GST input tax credit can be claimed only on the basis of a valid tax invoice.', 'GST इनपुट टॅक्स क्रेडिट फक्त वैध कर बीजकाच्या आधारेच घेता येते.', 'Input tax credit needs a valid tax invoice (with the supplier''s GSTIN), along with receipt of the goods or services.', 'Input tax credit needs a valid tax invoice (with the supplier''s GSTIN), along with receipt of the goods or services.', 'इनपुट कर क्रेडिटसाठी वैध कर बीजक (पुरवठादाराच्या GSTIN सह) व माल/सेवा मिळणे आवश्यक.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1359, 215, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1360, 215, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (216, 'D22-0001', NULL, 'D22', 'workplace_ethics', 2, 'Remember', 'single', 'Under central government leave rules, casual leave:', 'केंद्र सरकारच्या रजा नियमांनुसार नैमित्तिक रजा:', 'Under the CCS (Leave) Rules, casual leave is not a recognised kind of leave. It cannot be combined with regular leave or carried forward.', 'Under the CCS (Leave) Rules, casual leave is not a recognised kind of leave. It cannot be combined with regular leave or carried forward.', 'CCS (रजा) नियमांनुसार नैमित्तिक रजा ही मान्य रजा नाही; ती इतर नियमित रजेसोबत जोडता येत नाही व पुढे नेता येत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1361, 216, 1, 'Is not a recognised leave and is not combined with others', 'मान्यताप्राप्त रजा नाही व इतर रजेशी जोडली जात नाही', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1362, 216, 2, 'Can be carried forward to the next calendar year', 'पुढील कॅलेंडर वर्षात पुढे नेता येते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1363, 216, 3, 'Can be encashed along with earned leave at retirement', 'निवृत्तीच्या वेळी अर्जित रजेसोबत रोखीत मिळते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1364, 216, 4, 'Needs a medical certificate beyond two days', 'दोन दिवसांपेक्षा जास्त असल्यास वैद्यकीय प्रमाणपत्र लागते', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (217, 'D22-0002', NULL, 'D22', 'workplace_ethics', 3, 'Apply', 'single', 'A probationer''s work has been weak but improving. The probation period ends next week. What is the usual course?', 'एका परिविक्षाधीन कर्मचाऱ्याचे काम कमकुवत पण सुधारत आहे. परिविक्षा कालावधी पुढील आठवड्यात संपतो. सहसा काय केले जाते?', 'When performance is improving but not yet adequate, probation is extended as the rules allow, with clear targets. Confirmation is not automatic.', 'When performance is improving but not yet adequate, probation is extended as the rules allow, with clear targets. Confirmation is not automatic.', 'कामगिरी सुधारत आहे पण अजून पुरेशी नाही तेव्हा नियमानुसार स्पष्ट उद्दिष्टांसह परिविक्षा वाढवतात; कायमीकरण आपोआप होत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1365, 217, 1, 'Extend probation as the rules allow, with clear targets', 'नियमानुसार स्पष्ट उद्दिष्टांसह परिविक्षा वाढवणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1366, 217, 2, 'Confirm him automatically, as the period has ended', 'कालावधी संपल्याने आपोआप कायम करणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1367, 217, 3, 'Terminate his service, as the work has been weak', 'काम कमकुवत असल्याने सेवा समाप्त करणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1368, 217, 4, 'Transfer him to another department on probation', 'परिविक्षेवर दुसऱ्या विभागात बदली करणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (218, 'D23-0001', NULL, 'D23', 'workplace_ethics', 2, 'Understand', 'single', 'What is a Training Needs Analysis (TNA) mainly used for?', 'प्रशिक्षण गरज विश्लेषण (TNA) मुख्यतः कशासाठी वापरतात?', 'A TNA compares the competence required with the competence held, so that training targets the real gaps.', 'A TNA compares the competence required with the competence held, so that training targets the real gaps.', 'TNA आवश्यक व सध्याच्या क्षमतेची तुलना करते, जेणेकरून प्रशिक्षण खऱ्या उणिवांवर केंद्रित होते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1369, 218, 1, 'Finding the gap between required and current competence', 'आवश्यक व सध्याच्या क्षमतेतील अंतर शोधणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1370, 218, 2, 'Fixing the training budget for each department', 'प्रत्येक विभागाचा प्रशिक्षण अर्थसंकल्प ठरवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1371, 218, 3, 'Counting training hours completed by each employee', 'प्रत्येक कर्मचाऱ्याचे पूर्ण झालेले प्रशिक्षण तास मोजणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1372, 218, 4, 'Selecting trainers and venues for the annual calendar', 'वार्षिक दिनदर्शिकेसाठी प्रशिक्षक व स्थळ निवडणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (219, 'D23-0002', NULL, 'D23', 'workplace_ethics', 3, 'Analyse', 'single', 'Which is the best evidence that a course improved on-the-job performance?', 'अभ्यासक्रमामुळे कामावरील कामगिरी सुधारली याचा सर्वोत्तम पुरावा कोणता?', 'On-the-job behaviour is Kirkpatrick level 3; an end-of-course test is level 2 and feedback forms are level 1.', 'On-the-job behaviour is Kirkpatrick level 3; an end-of-course test is level 2 and feedback forms are level 1.', 'कामावरील वर्तन हा किर्कपॅट्रिक स्तर 3; अभ्यासक्रम-अखेरची चाचणी स्तर 2 व अभिप्राय अर्ज स्तर 1.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1373, 219, 1, 'Supervisor observation of the skill on the job months later', 'काही महिन्यांनी कामावरील कौशल्याचे पर्यवेक्षकाचे निरीक्षण', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1374, 219, 2, 'High scores in the test taken at the end of the course', 'अभ्यासक्रमाच्या शेवटी घेतलेल्या चाचणीतील उच्च गुण', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1375, 219, 3, 'Positive feedback forms filled in by participants', 'सहभागींनी भरलेले सकारात्मक अभिप्राय अर्ज', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1376, 219, 4, 'Full attendance by all the nominated staff', 'सर्व नामनिर्देशित कर्मचाऱ्यांची पूर्ण उपस्थिती', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (220, 'D23-0003', NULL, 'D23', 'workplace_ethics', 2, 'Remember', 'single', 'In the Kirkpatrick model, what does Level 2 measure?', 'किर्कपॅट्रिक मॉडेलमध्ये स्तर 2 काय मोजतो?', 'Kirkpatrick''s levels are: 1 Reaction, 2 Learning, 3 Behaviour, 4 Results.', 'Kirkpatrick''s levels are: 1 Reaction, 2 Learning, 3 Behaviour, 4 Results.', 'कर्कपॅट्रिक स्तर: 1 प्रतिक्रिया, 2 शिक्षण, 3 वर्तन, 4 परिणाम.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1377, 220, 1, 'Learning', 'शिकणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1378, 220, 2, 'Reaction', 'प्रतिक्रिया', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1379, 220, 3, 'Behaviour', 'वर्तन', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1380, 220, 4, 'Results', 'परिणाम', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (221, 'D24-0001', NULL, 'D24', 'workplace_ethics', 2, 'Remember', 'multi', 'Which of these are among India''s four labour codes?', 'यापैकी कोणत्या भारताच्या चार कामगार संहितांपैकी आहेत?', 'The four codes are Wages, Industrial Relations, Social Security, and Occupational Safety, Health and Working Conditions. Contract labour is covered under the OSH Code.', 'The four codes are Wages, Industrial Relations, Social Security, and Occupational Safety, Health and Working Conditions. Contract labour is covered under the OSH Code.', 'चार संहिता: वेतन, औद्योगिक संबंध, सामाजिक सुरक्षा, आणि व्यावसायिक सुरक्षा, आरोग्य व कामाच्या अटी. कंत्राटी कामगार OSH संहितेत येतात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1381, 221, 1, 'Code on Wages', 'वेतन संहिता', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1382, 221, 2, 'Industrial Relations Code', 'औद्योगिक संबंध संहिता', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1383, 221, 3, 'Occupational Safety, Health and Working Conditions Code', 'व्यावसायिक सुरक्षा, आरोग्य व कामाच्या परिस्थितीची संहिता', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1384, 221, 4, 'Code on Social Security', 'सामाजिक सुरक्षा संहिता', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1385, 221, 5, 'Code on Contract Labour Licensing', 'कंत्राटी कामगार परवाना संहिता', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (222, 'D24-0002', NULL, 'D24', 'workplace_ethics', 2, 'Understand', 'truefalse', 'If a contractor fails to pay wages to contract labour, the principal employer is liable to pay them.', 'कंत्राटदाराने कंत्राटी कामगारांचे वेतन न दिल्यास मुख्य नियोक्त्याला ते द्यावे लागते.', 'The principal employer must ensure that contract labour is paid. If the contractor defaults, the principal employer pays and recovers the amount from the contractor.', 'The principal employer must ensure that contract labour is paid. If the contractor defaults, the principal employer pays and recovers the amount from the contractor.', 'कंत्राटी कामगारांना वेतन मिळेल याची जबाबदारी मुख्य मालकाची; कंत्राटदाराने न दिल्यास मुख्य मालक देऊन ती रक्कम कंत्राटदाराकडून वसूल करतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1386, 222, 1, 'True', 'बरोबर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1387, 222, 2, 'False', 'चूक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (223, 'D24-0003', NULL, 'D24', 'workplace_ethics', 3, 'Apply', 'sjt', 'Contract cleaning staff at a station complain to you that their wages for last month have not been paid. What do you do?', 'स्थानकावरील कंत्राटी स्वच्छता कर्मचारी तुमच्याकडे तक्रार करतात की मागील महिन्याचे वेतन मिळालेले नाही. तुम्ही काय कराल?', 'Maha Metro, as principal employer, has a duty here. Record the complaint and route it to the contract-managing department. Ignoring it or advising a strike is wrong.', 'Maha Metro, as principal employer, has a duty here. Record the complaint and route it to the contract-managing department. Ignoring it or advising a strike is wrong.', 'मुख्य मालक म्हणून महा मेट्रोची जबाबदारी आहे; तक्रार नोंदवून कंत्राट सांभाळणाऱ्या विभागाकडे पाठवा. दुर्लक्ष करणे किंवा संपाचा सल्ला देणे चुकीचे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1388, 223, 1, 'Record it and refer it to the department managing the contract', 'नोंद करा व करार हाताळणाऱ्या विभागाकडे पाठवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1389, 223, 2, 'Tell them it is between them and their contractor', 'हा त्यांचा व त्यांच्या कंत्राटदाराचा प्रश्न आहे असे सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1390, 223, 3, 'Call the contractor''s supervisor and ask him to pay quickly', 'कंत्राटदाराच्या पर्यवेक्षकाला फोन करून लवकर पैसे देण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1391, 223, 4, 'Advise them to stop work until wages are paid', 'वेतन मिळेपर्यंत काम थांबवण्याचा सल्ला द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (224, 'D25-0001', NULL, 'D25', 'workplace_ethics', 3, 'Apply', 'single', 'A department plans to split a requirement into several smaller purchase orders so that each falls within a lower approval limit. This is:', 'एक विभाग एकच गरज अनेक लहान खरेदी आदेशांमध्ये विभागण्याचे ठरवतो जेणेकरून प्रत्येक आदेश कमी मंजुरी मर्यादेत येईल. हे:', 'The GFR prohibits splitting a requirement to avoid a higher sanction. This applies whatever the urgency or the platform used.', 'The GFR prohibits splitting a requirement to avoid a higher sanction. This applies whatever the urgency or the platform used.', 'उच्च मंजुरी टाळण्यासाठी मागणी विभागणे GFR नुसार निषिद्ध आहे – निकड किंवा प्लॅटफॉर्म कोणताही असो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1392, 224, 1, 'Not allowed – splitting to avoid sanction is prohibited', 'परवानगी नाही – मंजुरी टाळण्यासाठी विभागणी निषिद्ध आहे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1393, 224, 2, 'Allowed, if the total stays within the annual budget', 'एकूण रक्कम वार्षिक अर्थसंकल्पात असल्यास परवानगी आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1394, 224, 3, 'Allowed, if the requirement is certified as urgent', 'गरज तातडीची म्हणून प्रमाणित असल्यास परवानगी आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1395, 224, 4, 'Allowed, if each order is placed through GeM', 'प्रत्येक आदेश GeM द्वारे दिल्यास परवानगी आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (225, 'D25-0002', NULL, 'D25', 'workplace_ethics', 3, 'Apply', 'single', 'An item you need is listed on GeM by several sellers. A local supplier, not on GeM, offers a lower price by email. What is the correct approach?', 'तुम्हाला हवी असलेली वस्तू GeM वर अनेक विक्रेत्यांकडे उपलब्ध आहे. GeM वर नसलेला स्थानिक पुरवठादार ई-मेलने कमी किंमत देतो. योग्य पद्धत कोणती?', 'For items available on GeM, procurement through GeM is mandatory. Its bid or reverse-auction option gives the competitive price.', 'For items available on GeM, procurement through GeM is mandatory. Its bid or reverse-auction option gives the competitive price.', 'GeM वर उपलब्ध वस्तूंची खरेदी GeM मार्फतच अनिवार्य; त्याचा बिड/रिव्हर्स-ऑक्शन पर्याय स्पर्धात्मक दर देतो.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1396, 225, 1, 'Buy through GeM, using its bid or reverse-auction option', 'GeM मार्फत, त्याचा बोली किंवा रिव्हर्स-लिलाव पर्याय वापरून खरेदी करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1397, 225, 2, 'Buy from the local supplier, as the price is lower', 'किंमत कमी असल्याने स्थानिक पुरवठादाराकडून खरेदी करा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1398, 225, 3, 'Call quotations from three local suppliers outside GeM', 'GeM बाहेर तीन स्थानिक पुरवठादारांकडून दरपत्रके मागवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1399, 225, 4, 'Ask the local supplier to match the lowest GeM price', 'स्थानिक पुरवठादाराला सर्वात कमी GeM किमतीशी जुळवण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (226, 'D25-0003', NULL, 'D25', 'workplace_ethics', 2, 'Understand', 'single', 'In bid evaluation, ''L1'' means:', 'निविदा मूल्यमापनात ''L1'' म्हणजे:', 'L1 is the lowest bid after evaluation, among bids found responsive, not simply the lowest figure quoted.', 'L1 is the lowest bid after evaluation, among bids found responsive, not simply the lowest figure quoted.', 'L1 म्हणजे मूल्यमापनानंतर, प्रतिसादक्षम ठरलेल्या बोलींपैकी सर्वात कमी – फक्त सर्वात कमी नमूद आकडा नव्हे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1400, 226, 1, 'The lowest evaluated responsive bid', 'सर्वात कमी मूल्यमापित पात्र निविदा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1401, 226, 2, 'The lowest quoted bid, before evaluation', 'मूल्यमापनापूर्वीची सर्वात कमी नमूद निविदा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1402, 226, 3, 'The first bid to be opened', 'उघडलेली पहिली निविदा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1403, 226, 4, 'The bidder with the best technical score', 'सर्वोत्तम तांत्रिक गुण असलेला निविदाकार', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (227, 'D26-0001', NULL, 'D26', 'workplace_ethics', 3, 'Apply', 'single', 'A contractor''s work is delayed 30 days because the employer handed over the site late. What is the contractor normally entitled to?', 'नियोक्त्याने साइट उशिरा दिल्याने कंत्राटदाराचे काम 30 दिवस उशिरा होते. कंत्राटदाराला सामान्यतः कशाचा हक्क असतो?', 'A delay caused by the employer entitles the contractor to an extension of time. Liquidated damages cannot be levied for that period.', 'A delay caused by the employer entitles the contractor to an extension of time. Liquidated damages cannot be levied for that period.', 'मालकामुळे झालेल्या विलंबासाठी कंत्राटदाराला मुदतवाढ मिळते; त्या कालावधीसाठी नुकसानभरपाई (LD) आकारता येत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1404, 227, 1, 'An extension of time without liquidated damages', 'नुकसानभरपाईशिवाय मुदतवाढ', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1405, 227, 2, 'Waiver of damages, but no change to the completion date', 'नुकसानभरपाई माफ, पण पूर्णत्वाची तारीख तीच', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1406, 227, 3, 'Nothing, as delays are the contractor''s risk', 'काहीच नाही, कारण विलंब ही कंत्राटदाराची जोखीम आहे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1407, 227, 4, 'Termination of the contract with full payment', 'पूर्ण देयकासह करार समाप्ती', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (228, 'D26-0002', NULL, 'D26', 'workplace_ethics', 2, 'Understand', 'single', 'When is a variation order issued?', 'बदल आदेश (variation order) केव्हा दिला जातो?', 'A variation order formally changes the contracted scope, together with its cost and time effects.', 'A variation order formally changes the contracted scope, together with its cost and time effects.', 'व्हेरिएशन ऑर्डर कराराच्या कामाची व्याप्ती, खर्च व वेळेच्या परिणामासह औपचारिकपणे बदलते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1408, 228, 1, 'When the scope of work under the contract changes', 'करारातील कामाची व्याप्ती बदलल्यावर', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1409, 228, 2, 'When the contract price is revised for inflation', 'महागाईनुसार कराराची किंमत सुधारल्यावर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1410, 228, 3, 'When the completion date is extended', 'पूर्णत्वाची तारीख वाढवल्यावर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1411, 228, 4, 'When a bill is held for deductions', 'वजावटीसाठी बिल रोखल्यावर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (229, 'D27-0001', NULL, 'D27', 'workplace_ethics', 3, 'Apply', 'numeric', 'Annual demand is 1,200 units, ordering cost is ₹100 per order and holding cost is ₹24 per unit per year. What is the EOQ (units)?', 'वार्षिक मागणी 1,200 नग, प्रति ऑर्डर खर्च ₹100 व धारण खर्च ₹24 प्रति नग प्रति वर्ष आहे. EOQ किती (नग)?', 'EOQ = √(2DS/H) = √(2×1200×100/24) = 100', 'EOQ = √(2DS/H) = √(2×1200×100/24) = 100', 'EOQ = √(2DS/H) = √(2×1200×100/24) = 100', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (230, 'D27-0002', NULL, 'D27', 'workplace_ethics', 4, 'Analyse', 'single', 'A spare has low annual consumption value but its absence would stop trains. How should it be managed?', 'एका सुट्या भागाचे वार्षिक वापर मूल्य कमी आहे, पण तो नसल्यास गाड्या थांबतील. त्याचे व्यवस्थापन कसे करावे?', 'ABC looks at value; VED looks at criticality. A cheap but vital spare needs safety stock.', 'ABC looks at value; VED looks at criticality. A cheap but vital spare needs safety stock.', 'ABC मूल्य पाहते, VED महत्त्व पाहते; स्वस्त पण अत्यावश्यक सुट्या भागासाठी सुरक्षा साठा आवश्यक.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1412, 230, 1, 'As a vital (VED) item with safety stock, though ''C'' in ABC', 'ABC मध्ये ''C'' असला तरी सुरक्षा साठ्यासह महत्त्वाची (VED) वस्तू म्हणून', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1413, 230, 2, 'As a ''C'' item, ordered only when stock runs out', '''C'' वस्तू म्हणून, साठा संपल्यावरच मागवून', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1414, 230, 3, 'As an ''A'' item, reviewed and counted every week', '''A'' वस्तू म्हणून, दर आठवड्याला आढावा व मोजणी करून', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1415, 230, 4, 'As a non-stock item, bought from the market when needed', 'साठा न ठेवता, गरज पडल्यावर बाजारातून खरेदी करून', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (231, 'D27-0003', NULL, 'D27', 'workplace_ethics', 1, 'Remember', 'single', 'Under FIFO issue of stores:', 'FIFO पद्धतीने भांडार वस्तू देताना:', 'First-in, first-out issues the oldest stock first, which avoids items expiring or deteriorating on the shelf.', 'First-in, first-out issues the oldest stock first, which avoids items expiring or deteriorating on the shelf.', 'प्रथम आलेले प्रथम दिले (FIFO) – जुना साठा आधी दिल्याने वस्तू कालबाह्य किंवा खराब होत नाहीत.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1416, 231, 1, 'The oldest stock is issued first', 'सर्वात जुना साठा आधी दिला जातो', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1417, 231, 2, 'The newest stock is issued first', 'सर्वात नवा साठा आधी दिला जातो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1418, 231, 3, 'The cheapest stock is issued first', 'सर्वात स्वस्त साठा आधी दिला जातो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1419, 231, 4, 'The nearest stock is issued first', 'सर्वात जवळचा साठा आधी दिला जातो', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (232, 'D28-0001', NULL, 'D28', 'workplace_ethics', 2, 'Understand', 'multi', 'Which of these are non-fare revenue for a metro?', 'यापैकी मेट्रोसाठी भाडेतर महसूल कोणते?', 'Non-fare revenue comes from assets other than travel. Smart-card value is fare revenue, and penalties are not a business revenue stream.', 'Non-fare revenue comes from assets other than travel. Smart-card value is fare revenue, and penalties are not a business revenue stream.', 'प्रवासाव्यतिरिक्त मालमत्तेतून मिळणारा महसूल नॉन-फेअर; स्मार्ट कार्ड मूल्य हे भाडे-उत्पन्न व दंड हा व्यावसायिक महसूल नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1420, 232, 1, 'Advertising on stations and trains', 'स्थानके व गाड्यांवरील जाहिरात', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1421, 232, 2, 'Leasing of retail space', 'किरकोळ जागा भाड्याने देणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1422, 232, 3, 'Station naming rights', 'स्थानक नामकरण हक्क', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1423, 232, 4, 'Sale of smart cards with stored value', 'मूल्य साठवलेल्या स्मार्ट कार्डची विक्री', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1424, 232, 5, 'Penalties collected for ticketless travel', 'विनातिकीट प्रवासासाठी वसूल दंड', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (233, 'D28-0002', NULL, 'D28', 'workplace_ethics', 2, 'Understand', 'single', 'What does Transit Oriented Development (TOD) aim to do?', 'ट्रान्झिट ओरिएंटेड डेव्हलपमेंट (TOD) चे उद्दिष्ट काय आहे?', 'TOD places dense, mixed-use development within walking distance of stations to raise ridership and reduce car dependence.', 'TOD places dense, mixed-use development within walking distance of stations to raise ridership and reduce car dependence.', 'TOD स्थानकांपासून चालण्याच्या अंतरावर दाट, मिश्र-वापर विकास करते – प्रवासी संख्या वाढवून वाहनांवरील अवलंबन कमी करते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1425, 233, 1, 'Concentrate homes and jobs within walking distance of stations', 'स्थानकांपासून चालण्याच्या अंतरात घरे व रोजगार केंद्रित करणे', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1426, 233, 2, 'Build large multi-level car parks at every metro station', 'प्रत्येक मेट्रो स्थानकावर मोठी बहुमजली वाहनतळे बांधणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1427, 233, 3, 'Move offices away from congested city centres to suburbs', 'गर्दीच्या शहर-केंद्रांपासून कार्यालये उपनगरांत हलवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1428, 233, 4, 'Reserve land along the line for future tracks', 'भविष्यातील रुळांसाठी मार्गालगत जमीन राखून ठेवणे', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (234, 'D29-0001', NULL, 'D29', 'workplace_ethics', 3, 'Apply', 'single', 'A vendor asks for urgent remote desktop access to a SCADA server from the internet to fix a bug. What is the right approach?', 'एक विक्रेता बग दुरुस्त करण्यासाठी इंटरनेटवरून SCADA सर्व्हरचा तातडीचा रिमोट डेस्कटॉप प्रवेश मागतो. योग्य पद्धत कोणती?', 'Operational systems must never be exposed to the internet. Controlled, logged, time-limited access through a jump server is the safe route.', 'Operational systems must never be exposed to the internet. Controlled, logged, time-limited access through a jump server is the safe route.', 'परिचालन प्रणाली इंटरनेटवर कधीही उघड करू नये; जंप सर्व्हरद्वारे नियंत्रित, नोंदित व मर्यादित वेळेचा प्रवेश हाच सुरक्षित मार्ग.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1429, 234, 1, 'Give approved, time-limited access via the jump server, then revoke', 'जंप सर्व्हरद्वारे मंजूर, मर्यादित-वेळेचा प्रवेश द्या, मग रद्द करा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1430, 234, 2, 'Open the RDP port on the firewall for one day only', 'फायरवॉलवर RDP पोर्ट फक्त एका दिवसासाठी उघडा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1431, 234, 3, 'Share the admin password by phone and change it afterwards', 'फोनवर ॲडमिन पासवर्ड सांगा व नंतर बदला', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1432, 234, 4, 'Refuse all remote support for operational systems permanently', 'परिचालन प्रणालींसाठी सर्व दूरस्थ मदत कायमची नाकारा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (235, 'D29-0002', NULL, 'D29', 'workplace_ethics', 2, 'Remember', 'multi', 'The CIA triad of information security consists of:', 'माहिती सुरक्षेच्या CIA त्रयीमध्ये काय येते?', 'CIA stands for Confidentiality, Integrity and Availability. Authentication and accountability are supporting controls.', 'CIA stands for Confidentiality, Integrity and Availability. Authentication and accountability are supporting controls.', 'CIA म्हणजे गोपनीयता, अखंडता व उपलब्धता; प्रमाणीकरण व उत्तरदायित्व ही पूरक नियंत्रणे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1433, 235, 1, 'Confidentiality', 'गोपनीयता', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1434, 235, 2, 'Integrity', 'अखंडता', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1435, 235, 3, 'Availability', 'उपलब्धता', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1436, 235, 4, 'Authentication', 'प्रमाणीकरण', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1437, 235, 5, 'Accountability', 'उत्तरदायित्व', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (236, 'D29-0003', NULL, 'D29', 'workplace_ethics', 2, 'Understand', 'single', 'What does the 3-2-1 backup rule mean?', '3-2-1 बॅकअप नियम म्हणजे काय?', 'Keep three copies of the data on two kinds of media, with one copy off-site, so that a single failure or disaster cannot destroy all of them.', 'Keep three copies of the data on two kinds of media, with one copy off-site, so that a single failure or disaster cannot destroy all of them.', 'डेटाच्या तीन प्रती, दोन प्रकारच्या माध्यमांवर, एक प्रत बाहेरील ठिकाणी – एका बिघाडात किंवा आपत्तीत सर्व नष्ट होत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1438, 236, 1, '3 copies of data, on 2 types of media, 1 kept off-site', 'डेटाच्या 3 प्रती, 2 प्रकारच्या माध्यमांवर, 1 बाहेरील ठिकाणी', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1439, 236, 2, '3 daily backups, 2 weekly backups, 1 monthly backup', '3 दैनिक, 2 साप्ताहिक व 1 मासिक बॅकअप', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1440, 236, 3, '3 servers, 2 data centres, 1 cloud provider', '3 सर्व्हर, 2 डेटा सेंटर, 1 क्लाउड पुरवठादार', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1441, 236, 4, 'Restore tests every 3 months, 2 people, 1 report', 'दर 3 महिन्यांनी पुनर्स्थापना चाचणी, 2 व्यक्ती, 1 अहवाल', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (237, 'D30-0001', NULL, 'D30', 'workplace_ethics', 1, 'Remember', 'numeric', 'Under the RTI Act, 2005, within how many days must information normally be provided to the applicant?', 'माहिती अधिकार अधिनियम, 2005 नुसार अर्जदाराला सामान्यतः किती दिवसांत माहिती द्यावी लागते?', 'Section 7(1) of the RTI Act requires a reply within 30 days of receiving the request.', 'Section 7(1) of the RTI Act requires a reply within 30 days of receiving the request.', 'RTI कायद्याचे कलम 7(1): अर्ज मिळाल्यापासून 30 दिवसांत उत्तर द्यावे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (238, 'D30-0002', NULL, 'D30', 'workplace_ethics', 2, 'Remember', 'fill_blank', 'Under the RTI Act, information concerning the life or liberty of a person must be provided within ____ hours.', 'माहिती अधिकार अधिनियमानुसार एखाद्या व्यक्तीच्या जीवन किंवा स्वातंत्र्याशी संबंधित माहिती ____ तासांत द्यावी लागते.', 'The proviso to Section 7(1) requires information concerning life or liberty to be provided within 48 hours.', 'The proviso to Section 7(1) requires information concerning life or liberty to be provided within 48 hours.', 'कलम 7(1) च्या परंतुकानुसार जीवन किंवा स्वातंत्र्याशी संबंधित माहिती 48 तासांत द्यावी.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (239, 'D30-0003', NULL, 'D30', 'workplace_ethics', 3, 'Apply', 'single', 'An RTI application asks for information held by another public authority. What should the PIO do?', 'माहिती अधिकार अर्जात दुसऱ्या सार्वजनिक प्राधिकरणाकडे असलेली माहिती मागितली आहे. जन माहिती अधिकाऱ्याने काय करावे?', 'Section 6(3) requires the application to be transferred to the authority that holds the information within 5 days, and the applicant informed.', 'Section 6(3) requires the application to be transferred to the authority that holds the information within 5 days, and the applicant informed.', 'कलम 6(3): माहिती ज्या प्राधिकरणाकडे आहे त्यांच्याकडे 5 दिवसांत अर्ज हस्तांतरित करून अर्जदाराला कळवावे.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1442, 239, 1, 'Transfer it to that authority within 5 days and inform the applicant', '5 दिवसांत तो अर्ज त्या प्राधिकरणाकडे पाठवा व अर्जदाराला कळवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1443, 239, 2, 'Reject it, as the information is not held by this office', 'माहिती या कार्यालयाकडे नसल्याने अर्ज फेटाळा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1444, 239, 3, 'Return the fee and ask the applicant to apply afresh', 'शुल्क परत करा व नव्याने अर्ज करण्यास सांगा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1445, 239, 4, 'Collect the information from that authority and reply within 30 days', 'त्या प्राधिकरणाकडून माहिती मिळवून 30 दिवसांत उत्तर द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (240, 'D30-0004', NULL, 'D30', 'workplace_ethics', 3, 'Apply', 'short_text', 'Draft a short note (6–10 lines) on file seeking approval to conduct a one-day fire safety refresher for 30 station staff at the CoE.', 'CoE मध्ये 30 स्थानक कर्मचाऱ्यांसाठी एक दिवसीय अग्निसुरक्षा उजळणी प्रशिक्षण घेण्यासाठी मंजुरी मागणारी छोटी टिप्पणी (6–10 ओळी) फाइलवर लिहा.', 'Review operational protocols and standard safety manuals.', 'Operational correctness derived from G&SR.', 'जी आणि एसआर नियमांनुसार अचूक कार्यपद्धती.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (241, 'D31-0001', NULL, 'D31', 'workplace_ethics', 2, 'Remember', 'single', 'Who approves the annual financial statements of a company before they are placed before the shareholders?', 'भागधारकांसमोर ठेवण्यापूर्वी कंपनीची वार्षिक वित्तीय विवरणपत्रे कोण मंजूर करते?', 'Under the Companies Act the Board approves the financial statements. They are then audited and placed before the shareholders at the AGM.', 'Under the Companies Act the Board approves the financial statements. They are then audited and placed before the shareholders at the AGM.', 'कंपनी कायद्यानुसार संचालक मंडळ वित्तीय विवरणे मंजूर करते; त्यानंतर ती लेखापरीक्षित होऊन वार्षिक सभेत भागधारकांसमोर ठेवली जातात.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1446, 241, 1, 'The Board of Directors', 'संचालक मंडळ', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1447, 241, 2, 'The statutory auditor', 'वैधानिक लेखापरीक्षक', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1448, 241, 3, 'The audit committee alone', 'फक्त लेखापरीक्षा समिती', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1449, 241, 4, 'The company secretary', 'कंपनी सचिव', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (242, 'D31-0002', NULL, 'D31', 'workplace_ethics', 2, 'Understand', 'truefalse', 'Anonymous complaints sent to the vigilance department are always investigated.', 'दक्षता विभागाकडे आलेल्या निनावी तक्रारींची नेहमीच चौकशी केली जाते.', 'As per CVC guidelines, anonymous or pseudonymous complaints are generally not acted upon.', 'As per CVC guidelines, anonymous or pseudonymous complaints are generally not acted upon.', 'CVC मार्गदर्शक सूचनांनुसार निनावी किंवा टोपणनावाने आलेल्या तक्रारींवर सामान्यतः कारवाई होत नाही.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1450, 242, 1, 'True', 'बरोबर', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1451, 242, 2, 'False', 'चूक', 1, '');
INSERT IGNORE INTO question (id, code, parent_id, competency_code, topic_no, target_level, bloom, qtype, stem_en, stem_mr, solution_text, rationale_en, rationale_mr, time_seconds, difficulty, pool, status, author_emp_id, version_no) VALUES (243, 'D31-0003', NULL, 'D31', 'workplace_ethics', 2, 'Apply', 'single', 'A legal notice from a contractor arrives at your section. What should you do first?', 'कंत्राटदाराची कायदेशीर नोटीस तुमच्या विभागात येते. तुम्ही प्रथम काय कराल?', 'Legal notices carry deadlines. Register the notice and send it to the legal cell with the facts at once. Replying directly or waiting can harm Maha Metro''s case.', 'Legal notices carry deadlines. Register the notice and send it to the legal cell with the facts at once. Replying directly or waiting can harm Maha Metro''s case.', 'कायदेशीर नोटिशीला मुदत असते; नोंद करून तथ्यांसह विधी कक्षाकडे लगेच पाठवा. थेट उत्तर देणे किंवा वाट पाहणे महा मेट्रोच्या बाजूस हानी करू शकते.', 60, 'medium', 'practice', 'APPROVED', 'DEMO-SME', 1);
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1452, 243, 1, 'Diarise it and send it to the legal cell with facts and deadline', 'आवक नोंद करा व तथ्ये व मुदतीसह विधी कक्षाकडे पाठवा', 1, '');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1453, 243, 2, 'Reply to the contractor directly, as you know the facts', 'तथ्ये माहीत असल्याने कंत्राटदाराला थेट उत्तर द्या', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1454, 243, 3, 'Keep it on file until the contractor actually goes to court', 'कंत्राटदार प्रत्यक्ष न्यायालयात जाईपर्यंत फाइलमध्ये ठेवा', 0, 'Common operational shortcut or rule confusion');
INSERT IGNORE INTO question_option (id, question_id, ord, text_en, text_mr, correct, misconception) VALUES (1455, 243, 4, 'Forward it to the contractor''s engineer for comments', 'टिप्पणीसाठी कंत्राटदाराच्या अभियंत्याकडे पाठवा', 0, 'Common operational shortcut or rule confusion');